window.QB_TKP_B18 = [
{"id":"TKP-3051", "q":"Seorang warga bersuku Dayak datang ke loket kelurahan dengan logat yang kental dan terlihat kesulitan menjelaskan keperluannya dalam bahasa Indonesia. Antrean di belakangnya mulai ramai. Sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Mempersilakan warga tersebut bicara perlahan, mendengarkan dengan sabar, dan mengonfirmasi ulang maksudnya sebelum memproses berkas", "s":5},{"t":"Meminta warga tersebut menuliskan keperluannya di kertas agar lebih jelas, lalu memproses sesuai tulisan", "s":4},{"t":"Memanggil rekan yang bisa berbahasa daerah setempat untuk membantu menerjemahkan percakapan", "s":3},{"t":"Melayani warga berikutnya terlebih dahulu sambil meminta warga tersebut merumuskan kalimatnya", "s":2},{"t":"Menyuruh warga tersebut kembali lain waktu dengan pendamping yang fasih berbahasa Indonesia", "s":1}], "ex":"Pelayanan publik wajib inklusif tanpa membedakan suku. Mendengarkan dengan sabar adalah bentuk penghormatan sekaligus memastikan layanan tepat sasaran."},
{"id":"TKP-3052", "q":"Warga bersuku Bugis mengajukan surat keterangan usaha dengan nama yang mengandung gelar adat. Sistem administrasi hanya menerima nama tanpa gelar. Tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Menjelaskan dengan ramah keterbatasan sistem, mencatat nama sesuai KTP untuk administrasi, dan menghormati gelar adatnya dalam sapaan lisan", "s":5},{"t":"Memproses sesuai nama di KTP sambil menjelaskan bahwa gelar adat tetap dihormati di luar dokumen resmi", "s":4},{"t":"Meminta warga mengganti namanya agar sesuai format sistem", "s":3},{"t":"Menolak memproses sebelum warga menghilangkan gelar adat dari namanya", "s":2},{"t":"Menertawakan gelar adat tersebut karena dianggap mempersulit pekerjaan", "s":1}], "ex":"Aturan administrasi harus ditegakkan, tetapi identitas budaya warga tetap dihormati. Solusi terbaik menjembatani keduanya tanpa merendahkan."},
{"id":"TKP-3053", "q":"Di ruang tunggu puskesmas, dua kelompok warga berbeda suku terlibat adu mulut karena berebut kursi. Sebagai petugas yang melihat kejadian itu, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Melerai dengan tenang, menempatkan diri netral, dan mengatur ulang tempat duduk secara adil tanpa memihak suku mana pun", "s":5},{"t":"Meminta kedua kelompok tenang dan mengatur antrean ulang berdasarkan nomor urut", "s":4},{"t":"Memanggil petugas keamanan agar menangani keributan tersebut", "s":3},{"t":"Membiarkan mereka menyelesaikan sendiri karena bukan tugas pelayanan", "s":2},{"t":"Membela kelompok yang sukunya sama dengan Anda", "s":1}], "ex":"ASN harus netral dan menjadi penengah yang adil. Memihak berdasarkan kesamaan suku merusak kepercayaan publik terhadap aparatur."},
{"id":"TKP-3054", "q":"Seorang ibu bersuku Sasak tidak memahami prosedur pendaftaran sekolah anaknya karena brosur hanya berbahasa Indonesia formal. Yang paling tepat Anda lakukan sebagai petugas adalah ....", "opts":[{"t":"Menjelaskan prosedur dengan bahasa sederhana dan perlahan, memastikan ia paham tiap tahap sebelum pulang", "s":5},{"t":"Menjelaskan ulang poin-poin penting brosur dengan kalimat yang mudah dipahami", "s":4},{"t":"Memberikan brosur dan memintanya bertanya kepada tetangga yang lebih paham", "s":3},{"t":"Menyuruhnya datang kembali bersama anaknya yang bersekolah agar bisa menerjemahkan", "s":2},{"t":"Menganggapnya tidak peduli pendidikan anak karena tidak mau membaca brosur", "s":1}], "ex":"Hambatan bahasa bukan alasan menurunkan kualitas layanan. Kewajiban petugas memastikan informasi tersampaikan hingga dipahami warga."},
{"id":"TKP-3055", "q":"Warga bersuku Toraja meminta dispensasi waktu pengurusan berkas karena harus menghadiri upacara adat pemakaman keluarga yang berlangsung beberapa hari. Sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Memberikan informasi jelas tentang batas waktu pengurusan, menawarkan penjadwalan ulang, dan menyampaikan belasungkawa dengan tulus", "s":5},{"t":"Menjelaskan prosedur penjadwalan ulang dan mencatat keperluannya agar bisa dilayani sepulangnya dari upacara adat", "s":4},{"t":"Menyarankan warga mengutus anggota keluarga lain untuk mengurus berkas", "s":3},{"t":"Menolak memberikan dispensasi karena aturan waktu berlaku sama untuk semua", "s":2},{"t":"Menganggap upacara adat sebagai alasan mengada-ada untuk menunda urusan", "s":1}], "ex":"Menghormati upacara adat warga adalah wujud toleransi, sepanjang tetap dalam koridor aturan. Empati dan solusi administratif berjalan beriringan."},
{"id":"TKP-3056", "q":"Seorang pedagang bersuku Madura protes karena merasa dipersulit dalam pengurusan izin, padahal pedagang lain lancar. Ia menduga ada diskriminasi suku. Tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Mendengarkan keluhannya dengan serius, memeriksa ulang berkasnya secara transparan di hadapannya, dan menjelaskan tiap tahap proses", "s":5},{"t":"Menunjukkan alur dan persyaratan yang sama berlakunya untuk semua pemohon, lalu membantu melengkapi kekurangannya", "s":4},{"t":"Meminta ia bersabar karena semua pemohon diperlakukan sama", "s":3},{"t":"Mengatakan dugaannya tidak berdasar tanpa memeriksa berkasnya", "s":2},{"t":"Mengusirnya karena dianggap menuduh petugas berbuat curang", "s":1}], "ex":"Dugaan diskriminasi harus dijawab dengan transparansi, bukan dibantah begitu saja. Pelayanan yang terbuka memulihkan kepercayaan warga."},
{"id":"TKP-3057", "q":"Anak bersuku Papua diejek teman-temannya di sekolah karena warna kulit dan rambutnya. Sebagai guru, tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Menegur pelaku ejekan, memberikan pemahaman tentang keberagaman suku bangsa Indonesia, dan mendampingi anak tersebut agar percaya diri", "s":5},{"t":"Menasihati pelaku agar tidak mengejek dan mengajak seluruh kelas menghargai perbedaan", "s":4},{"t":"Memisahkan tempat duduk anak tersebut agar tidak diejek lagi", "s":3},{"t":"Menganggap ejekan itu candaan anak-anak yang wajar", "s":2},{"t":"Menyarankan orang tua memindahkan anaknya ke sekolah lain", "s":1}], "ex":"Pendidik wajib melindungi peserta didik dari perundungan berbasis suku dan menanamkan nilai Bhinneka Tunggal Ika sejak dini."},
{"id":"TKP-3058", "q":"Dalam musyawarah pembangunan desa, warga pendatang berbeda suku usulannya selalu diabaikan warga asli. Sebagai perangkat desa, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menegaskan bahwa setiap warga berhak menyampaikan pendapat, memfasilitasi giliran bicara yang adil, dan menampung usulan pendatang secara resmi", "s":5},{"t":"Meminta forum memberikan kesempatan kepada perwakilan pendatang untuk menyampaikan usulannya", "s":4},{"t":"Mencatat usulan pendatang secara pribadi untuk dibahas lain waktu", "s":3},{"t":"Membiarkan dinamika forum karena warga asli memang mayoritas", "s":2},{"t":"Mendukung pengabaian tersebut karena pendatang belum lama tinggal", "s":1}], "ex":"Demokrasi desa tidak mengenal kasta suku. Aparatur wajib menjamin hak partisipasi seluruh warga secara setara."},
{"id":"TKP-3059", "q":"Warga lanjut usia bersuku Batak berbicara dengan nada tinggi yang merupakan kebiasaannya, sehingga petugas lain mengira ia marah. Sikap Anda sebagai petugas yang melayaninya adalah ....", "opts":[{"t":"Tetap tenang dan ramah, memahami bahwa intonasi tinggi adalah ciri khas budayanya, dan melayani keperluannya dengan baik", "s":5},{"t":"Melayani seperti biasa tanpa terpengaruh nada bicaranya", "s":4},{"t":"Menegurnya agar berbicara lebih pelan di kantor pelayanan", "s":3},{"t":"Meminta rekan lain menggantikan melayaninya", "s":2},{"t":"Melaporkannya sebagai warga yang tidak sopan", "s":1}], "ex":"Perbedaan gaya komunikasi antarsuku bukan ketidaksopanan. Memahami konteks budaya mencegah kesalahpahaman dalam pelayanan."},
{"id":"TKP-3060", "q":"Seorang warga bersuku Ambon ingin mendaftarkan anaknya ke sekolah negeri, tetapi ditolak dengan alasan kuota penuh padahal masih ada bangku kosong. Ia curiga ada pilih kasih suku. Yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Memeriksa data kuota secara terbuka, menjelaskan sisa bangku yang ada, dan memproses pendaftarannya sesuai prosedur", "s":5},{"t":"Menunjukkan data daya tampung yang sebenarnya dan membantu proses pendaftarannya", "s":4},{"t":"Memintanya mendaftar ke sekolah lain yang kuotanya masih banyak", "s":3},{"t":"Menjelaskan bahwa penerimaan sudah sesuai prosedur tanpa menunjukkan data", "s":2},{"t":"Mengabaikan kecurigaannya karena menganggapnya tuduhan tak berdasar", "s":1}], "ex":"Kecurigaan warga dijawab dengan data terbuka. Transparansi adalah obat paling manjur bagi dugaan diskriminasi dalam layanan publik."},
{"id":"TKP-3061", "q":"Di kantor Anda akan diadakan acara kebersamaan. Sebagian pegawai mengusulkan acara dengan hiburan yang hanya mewakili satu budaya daerah. Sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Mengusulkan acara yang menampilkan keberagaman budaya seluruh pegawai agar semua merasa terwakili dan dihargai", "s":5},{"t":"Menyarankan panitia menambahkan unsur budaya daerah lain dalam acara tersebut", "s":4},{"t":"Mengikuti saja keputusan mayoritas panitia", "s":3},{"t":"Tidak ikut acara karena merasa budayanya tidak diwakili", "s":2},{"t":"Memprotes keras panitia karena dianggap tidak menghargai budaya lain", "s":1}], "ex":"Keberagaman di lingkungan kerja dirayakan dengan inklusivitas, bukan dominasi satu budaya. Usulan konstruktif lebih baik daripada protes atau apatis."},
{"id":"TKP-3062", "q":"Warga bersuku Bali datang mengurus izin keramaian untuk upacara adat di lingkungannya. Sebagian tetangga beda suku keberatan karena khawatir bising. Sebagai aparat kelurahan, tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Memfasilitasi musyawarah antara pemohon dan tetangga yang keberatan untuk menyepakati batas waktu dan teknis pelaksanaan", "s":5},{"t":"Memproses izin sesuai aturan sambil mengimbau pemohon menjaga ketertiban dan menghormati tetangga", "s":4},{"t":"Memberikan izin karena upacara adat adalah hak warga", "s":3},{"t":"Menolak izin demi menjaga ketenangan lingkungan", "s":2},{"t":"Membiarkan warga menyelesaikan sendiri tanpa campur tangan aparat", "s":1}], "ex":"Hak menjalankan tradisi adat dan hak tetangga atas ketenangan sama-sama dilindungi. Musyawarah menghasilkan solusi yang diterima semua pihak."},
{"id":"TKP-3063", "q":"Seorang siswa bersuku Minang diejek karena logatnya saat presentasi di kelas. Sebagai wali kelas, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menghentikan ejekan, menegaskan bahwa logat daerah adalah kekayaan budaya, dan memberi apresiasi atas keberanian siswa presentasi", "s":5},{"t":"Menegur siswa yang mengejek dan mengingatkan kelas untuk menghargai keberagaman", "s":4},{"t":"Menyarankan siswa tersebut berlatih berbicara tanpa logat", "s":3},{"t":"Menganggapnya sebagai dinamika kelas yang biasa", "s":2},{"t":"Menertawakan bersama karena logatnya memang lucu", "s":1}], "ex":"Logat daerah adalah identitas budaya yang patut dibanggakan, bukan bahan ejekan. Guru menjadi teladan penghargaan terhadap keberagaman."},
{"id":"TKP-3064", "q":"Warga pendatang dari suku berbeda ingin menjadi ketua RT, tetapi sebagian warga menolak dengan alasan ia bukan penduduk asli. Sebagai lurah, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menegaskan bahwa syarat menjadi ketua RT adalah administrasi kependudukan, bukan kesukuan, dan memastikan pemilihan berjalan demokratis", "s":5},{"t":"Menjelaskan aturan pemilihan RT yang tidak membedakan suku kepada warga yang menolak", "s":4},{"t":"Menunda pemilihan sampai ada calon dari penduduk asli", "s":3},{"t":"Mengikuti kehendak mayoritas warga yang menolak", "s":2},{"t":"Membatalkan pencalonannya demi menghindari konflik", "s":1}], "ex":"Jabatan publik di tingkat RT terbuka bagi seluruh warga yang memenuhi syarat administratif. Diskriminasi suku bertentangan dengan prinsip demokrasi."},
{"id":"TKP-3065", "q":"Petugas kesehatan akan melakukan penyuluhan di kampung masyarakat adat yang masih memegang kuat tradisi. Pendekatan yang paling tepat adalah ....", "opts":[{"t":"Berkunjung dengan sopan, meminta izin dan melibatkan tokoh adat, serta menyampaikan penyuluhan dengan menghormati nilai-nilai setempat", "s":5},{"t":"Menggandeng tokoh adat sebagai jembatan komunikasi dalam penyuluhan", "s":4},{"t":"Melakukan penyuluhan sesuai prosedur standar seperti di daerah lain", "s":3},{"t":"Memaksa warga mengikuti penyuluhan demi kesehatan mereka", "s":2},{"t":"Menganggap tradisi mereka menghambat program kesehatan", "s":1}], "ex":"Keberhasilan program di masyarakat adat ditentukan oleh penghormatan terhadap struktur sosial setempat. Tokoh adat adalah mitra, bukan penghalang."},
{"id":"TKP-3066", "q":"Dua pedagang di pasar bersitegang karena salah satu menuduh yang lain menggunakan ilmu gaib khas sukunya untuk melariskan dagangan. Sebagai petugas pasar, tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Melerai dan mengarahkan perselisihan ke persoalan nyata (lapak, harga), menolak tuduhan berbasis stereotip suku sebagai dasar penyelesaian", "s":5},{"t":"Mendamaikan keduanya dan menegaskan bahwa tuduhan tanpa bukti tidak dapat dijadikan alasan", "s":4},{"t":"Memisahkan lapak keduanya agar tidak bertengkar lagi", "s":3},{"t":"Membenarkan tuduhan tersebut karena mempercayai stereotip itu", "s":2},{"t":"Mengusir pedagang yang dituduh dari pasar", "s":1}], "ex":"Penyelesaian sengketa harus berbasis fakta, bukan stereotip suku. Aparatur tidak boleh melegitimasi prasangka dalam penegakan ketertiban."},
{"id":"TKP-3067", "q":"Warga bersuku Betawi mengeluh formulir pelayanan menggunakan istilah yang tidak ia pahami. Yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menjelaskan setiap istilah sulit dengan bahasa sehari-hari yang mudah dipahami hingga ia dapat mengisi formulir dengan benar", "s":5},{"t":"Membantu mengisi formulir sambil menjelaskan maksud tiap kolom", "s":4},{"t":"Memberikan contoh formulir yang sudah terisi sebagai panduan", "s":3},{"t":"Menyuruhnya bertanya kepada warga lain yang lebih paham", "s":2},{"t":"Menolak membantu karena mengisi formulir adalah tanggung jawab pemohon", "s":1}], "ex":"Pelayanan prima berarti memastikan warga benar-benar paham, bukan sekadar menyerahkan formulir. Bahasa yang sederhana adalah jembatan pelayanan."},
{"id":"TKP-3068", "q":"Dalam pembagian bantuan sosial, beredar kabar bahwa warga suku tertentu diprioritaskan. Sebagai petugas penyalur, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Membuka data penerima secara transparan, menunjukkan kriteria yang seragam, dan mempersilakan warga memeriksa daftar penerima", "s":5},{"t":"Menjelaskan kriteria penerima bantuan yang berlaku sama untuk semua suku", "s":4},{"t":"Memastikan penyaluran sesuai daftar tanpa menghiraukan kabar tersebut", "s":3},{"t":"Mengurangi jatah kelompok yang dikabarkan diprioritaskan agar terlihat adil", "s":2},{"t":"Menuduh penyebar kabar sebagai provokator tanpa klarifikasi", "s":1}], "ex":"Isu SARA dalam penyaluran bantuan diredam dengan keterbukaan data. Keadilan yang terlihat sama pentingnya dengan keadilan yang dijalankan."},
{"id":"TKP-3069", "q":"Seorang calon pegawai dari suku minoritas dinyatakan lulus seleksi administrasi, tetapi ada desakan agar ia digugurkan demi calon dari suku mayoritas. Sebagai panitia, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menolak desakan tersebut dan mempertahankan hasil seleksi berdasarkan merit karena rekrutmen ASN bebas dari diskriminasi suku", "s":5},{"t":"Menegaskan bahwa kelulusan ditentukan oleh nilai dan persyaratan, bukan kesukuan", "s":4},{"t":"Melaporkan desakan tersebut kepada atasan untuk ditindaklanjuti", "s":3},{"t":"Menunda pengumuman sampai situasi mereda", "s":2},{"t":"Menggugurkannya demi menjaga keharmonisan dengan kelompok mayoritas", "s":1}], "ex":"Sistem merit adalah benteng utama melawan diskriminasi suku dalam birokrasi. Integritas panitia diuji justru saat ada tekanan seperti ini."},
{"id":"TKP-3070", "q":"Warga bersuku Aceh meminta pelayanan dalam bahasa daerah karena tidak lancar berbahasa Indonesia. Petugas yang bisa bahasa tersebut sedang tidak ada. Tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Berkomunikasi dengan bahasa sederhana disertai isyarat yang jelas, bersabar, dan memastikan keperluannya terlayani dengan baik", "s":5},{"t":"Berusaha menjelaskan perlahan dengan kata-kata sederhana sampai warga memahami", "s":4},{"t":"Meminta warga menunggu sampai petugas yang bisa bahasa daerah datang", "s":3},{"t":"Memproses seadanya tanpa memastikan warga memahami", "s":2},{"t":"Menolak melayani karena terkendala bahasa", "s":1}], "ex":"Keterbatasan bahasa tidak boleh menjadi tembok pelayanan. Kesabaran dan komunikasi sederhana adalah wujud nyata negara hadir untuk semua suku."},
{"id":"TKP-3071", "q":"Tetangga Anda yang berbeda suku mengadakan hajatan dengan musik keras hingga larut malam saat anak Anda ujian keesokan harinya. Sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Mendatangi dengan sopan, menjelaskan situasi anak Anda, dan meminta pengurangan volume secara baik-baik", "s":5},{"t":"Berkomunikasi baik-baik meminta volume dikecilkan setelah jam tertentu", "s":4},{"t":"Melapor ke ketua RT tanpa berbicara dulu dengan tetangga", "s":3},{"t":"Mendiamkan saja sambil menahan kesal", "s":2},{"t":"Memaki tetangga karena menganggapnya tidak tahu adat bertetangga", "s":1}], "ex":"Persoalan antarwarga beda suku diselesaikan dengan komunikasi langsung yang sopan. Prasangka suku tidak boleh mewarnai penyelesaian masalah bertetangga."},
{"id":"TKP-3072", "q":"Di kelas, siswa dari berbagai suku dikelompokkan untuk tugas kelompok. Seorang siswa menolak sekelompok dengan siswa bersuku tertentu. Sebagai guru, tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Menjelaskan bahwa keberagaman adalah kekuatan kelompok, menetapkan pembagian kelompok yang adil, dan memantau kerja samanya", "s":5},{"t":"Menasihati siswa tersebut tentang pentingnya menghargai perbedaan suku", "s":4},{"t":"Menuruti keinginannya agar tugas berjalan lancar", "s":3},{"t":"Membiarkannya bekerja sendiri", "s":2},{"t":"Menghukumnya di depan kelas karena dianggap rasis", "s":1}], "ex":"Penolakan berbasis suku di lingkungan belajar harus diluruskan dengan pembinaan, bukan hukuman yang mempermalukan. Keberagaman justru memperkaya hasil kerja kelompok."},
{"id":"TKP-3073", "q":"Warga transmigran berbeda suku kesulitan beradaptasi dengan kebiasaan gotong royong di desa baru. Sebagai perangkat desa, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Mengajak dan mendampingi mereka terlibat dalam kegiatan gotong royong sambil menjelaskan nilai kebersamaannya dengan ramah", "s":5},{"t":"Mensosialisasikan jadwal dan tata cara gotong royong kepada warga pendatang", "s":4},{"t":"Membebaskan mereka dari kewajiban gotong royong karena berbeda latar budaya", "s":3},{"t":"Mewajibkan ikut serta dengan sanksi jika menolak", "s":2},{"t":"Mengucilkan mereka karena dianggap tidak mau membaur", "s":1}], "ex":"Integrasi warga pendatang dilakukan dengan ajakan dan pendampingan, bukan paksaan atau pengucilan. Budaya gotong royong diperkenalkan sebagai nilai bersama."},
{"id":"TKP-3074", "q":"Seorang warga bersuku Tionghoa merasa dipersulit saat mengurus dokumen kependudukan dibanding warga lain. Tindakan Anda sebagai petugas dukcapil yang paling tepat adalah ....", "opts":[{"t":"Memeriksa status berkasnya secara terbuka, memproses sesuai antrean dan prosedur, serta memastikan tidak ada perlakuan berbeda", "s":5},{"t":"Melayani sesuai prosedur standar dan menjelaskan progres berkasnya dengan transparan", "s":4},{"t":"Memintanya bersabar karena antrean memang panjang", "s":3},{"t":"Mengatakan perasaannya berlebihan tanpa memeriksa fakta", "s":2},{"t":"Mempersulitnya lebih lanjut karena tersinggung dituduh", "s":1}], "ex":"Setiap warga negara berhak atas layanan administrasi yang sama. Dugaan perlakuan berbeda harus dijawab dengan pelayanan yang terbukti adil."},
{"id":"TKP-3075", "q":"Dalam acara resmi kantor di daerah, tamu undangan dari berbagai suku hadir dengan pakaian adat masing-masing. Seorang rekan berkomentar merendahkan salah satu pakaian adat. Sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menegur rekan tersebut secara bijak dan menegaskan bahwa pakaian adat adalah kebanggaan budaya yang wajib dihormati", "s":5},{"t":"Mengingatkan rekan agar menjaga ucapan karena menghormati keberagaman adalah kewajiban ASN", "s":4},{"t":"Mengalihkan pembicaraan agar tidak berlanjut", "s":3},{"t":"Tertawa bersama karena menganggapnya candaan", "s":2},{"t":"Ikut berkomentar merendahkan agar terlihat akrab", "s":1}], "ex":"Pakaian adat adalah martabat suatu suku bangsa. ASN wajib menjadi garda depan penghormatan terhadap simbol-simbol budaya Indonesia."},
{"id":"TKP-3076", "q":"Seorang warga yang akan beribadah meminta pelayanannya dipercepat karena waktu ibadahnya hampir tiba, padahal keyakinannya berbeda dengan Anda. Sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Berusaha mempercepat prosesnya secara wajar tanpa melanggar antrean, sebagai bentuk penghormatan terhadap ibadahnya", "s":5},{"t":"Melayani dengan efisien dan menjelaskan bahwa Anda menghargai waktu ibadahnya", "s":4},{"t":"Memintanya antre seperti biasa karena aturan berlaku sama", "s":3},{"t":"Menundanya karena ibadahnya bukan urusan pelayanan", "s":2},{"t":"Mengejek keyakinannya karena berbeda dengan Anda", "s":1}], "ex":"Menghormati waktu ibadah warga adalah wujud toleransi beragama, sepanjang tidak mengorbankan keadilan bagi antrean lain."},
{"id":"TKP-3077", "q":"Warga penganut keyakinan lokal meminta surat keterangan untuk upacara ritualnya. Sebagian petugas ragu karena keyakinannya tidak umum. Tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Memproses suratnya sesuai prosedur seperti warga lainnya karena negara mengakui kebebasan berkeyakinan", "s":5},{"t":"Melayani sesuai aturan administrasi tanpa membedakan keyakinannya", "s":4},{"t":"Memintanya mengurus ke pemuka agamanya terlebih dahulu", "s":3},{"t":"Menolak karena keyakinannya tidak tercantum dalam formulir", "s":2},{"t":"Menyebarkan ke petugas lain bahwa keyakinannya sesat", "s":1}], "ex":"UUD 1945 menjamin kebebasan berkeyakinan bagi setiap warga. Aparat tidak berhak menghakimi keyakinan dalam pelayanan administrasi."},
{"id":"TKP-3078", "q":"Jadwal piket kantor Anda bentrok dengan waktu ibadah rutin Anda. Rekan satu tim berbeda keyakinan menawarkan bertukar jadwal. Sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menerima tawarannya dengan terima kasih dan bersedia bertukar jadwal saat ia membutuhkan untuk ibadahnya", "s":5},{"t":"Menyepakati pertukaran jadwal secara adil dan saling menguntungkan", "s":4},{"t":"Menolak dan tetap menjalankan piket sambil menunda ibadah", "s":3},{"t":"Memaksa rekan menggantikan tanpa imbalan", "s":2},{"t":"Melaporkan rekan karena dianggap mencampuri ibadah Anda", "s":1}], "ex":"Toleransi di tempat kerja diwujudkan dengan saling memberi ruang ibadah. Kebaikan yang timbal balik memperkuat kerukunan tim lintas keyakinan."},
{"id":"TKP-3079", "q":"Seorang warga nonmuslim bertanya tentang prosedur pengurusan jenazah yang berbeda dengan tata cara agama Anda. Yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Memberikan informasi prosedur secara profesional sesuai ketentuan, tanpa mencampuri tata cara keagamaannya", "s":5},{"t":"Menjelaskan alur administrasi yang berlaku umum untuk semua agama", "s":4},{"t":"Menyarankannya bertanya kepada tokoh agamanya saja", "s":3},{"t":"Menolak membantu karena tidak memahami agamanya", "s":2},{"t":"Menganggap tata cara agamanya menyulitkan pekerjaan", "s":1}], "ex":"Pelayanan administrasi bersifat netral terhadap agama. Petugas melayani prosedurnya, bukan menilai keyakinannya."},
{"id":"TKP-3080", "q":"Di lingkungan kantor, seorang pegawai baru berbeda agama merasa canggung saat jam makan siang di bulan puasa. Sikap Anda sebagai rekan yang paling tepat adalah ....", "opts":[{"t":"Bersikap biasa dan ramah, mempersilakan ia makan seperti biasa, serta menegaskan tidak perlu sungkan", "s":5},{"t":"Menyambutnya dengan hangat dan membuatnya nyaman tanpa membahas perbedaan", "s":4},{"t":"Menghindarinya saat jam makan agar tidak mengganggu yang berpuasa", "s":3},{"t":"Menyuruhnya makan di luar kantor", "s":2},{"t":"Menyindirnya karena tidak menghormati yang berpuasa", "s":1}], "ex":"Toleransi berarti saling memberi kenyamanan: yang berpuasa menghormati yang tidak, yang tidak berpuasa bersikap wajar tanpa berlebihan."},
{"id":"TKP-3081", "q":"Warga meminta izin mendirikan rumah ibadah di lingkungannya. Sebagian warga beda keyakinan menolak. Sebagai aparat, tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Memfasilitasi musyawarah sesuai regulasi pendirian rumah ibadah, memastikan syarat administratif dan dukungan lingkungan terpenuhi", "s":5},{"t":"Menjelaskan prosedur perizinan yang adil dan memediasi dialog antarwarga", "s":4},{"t":"Menunda izin sampai tidak ada lagi penolakan", "s":3},{"t":"Menolak izin demi menghindari kegaduhan", "s":2},{"t":"Memberikan izin diam-diam tanpa melibatkan warga sekitar", "s":1}], "ex":"Pendirian rumah ibadah diatur regulasi yang adil bagi semua agama. Musyawarah dan kepatuhan prosedur mencegah konflik horizontal."},
{"id":"TKP-3082", "q":"Anak didik Anda berbeda keyakinan dengan mayoritas kelas dan terlihat minder saat pelajaran agama. Sebagai guru, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Memastikan ia mendapat layanan pembelajaran agamanya dengan baik dan menumbuhkan rasa percaya dirinya sebagai bagian dari keberagaman kelas", "s":5},{"t":"Memberikan perhatian agar ia tidak merasa tersisih dalam pembelajaran", "s":4},{"t":"Membiarkannya mengikuti pelajaran agama mayoritas", "s":3},{"t":"Menyarankannya pindah sekolah yang sesuai keyakinannya", "s":2},{"t":"Menganggap keminderannya sebagai masalah pribadi", "s":1}], "ex":"Sekolah wajib memfasilitasi pendidikan agama setiap peserta didik sesuai keyakinannya. Tidak ada anak yang boleh minder karena minoritas."},
{"id":"TKP-3083", "q":"Rekan kerja mengajak Anda mengikuti ritual ibadah keyakinannya di luar jam kantor. Anda berbeda keyakinan. Sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menolak dengan halus dan hangat, menegaskan penghargaan atas ajakannya, tanpa merendahkan keyakinannya", "s":5},{"t":"Menolak secara sopan sambil menjaga hubungan baik sebagai rekan", "s":4},{"t":"Mengiyakan agar tidak menyinggung perasaannya", "s":3},{"t":"Menolak dengan kasar dan menjauhinya", "s":2},{"t":"Melaporkannya sebagai upaya pemaksaan keyakinan", "s":1}], "ex":"Menolak ajakan ibadah beda keyakinan adalah hak, tetapi caranya harus santun. Toleransi justru diuji dalam perbedaan yang paling sensitif."},
{"id":"TKP-3084", "q":"Dalam rapat desa, pembangunan balai warga direncanakan di lahan dekat rumah ibadah salah satu agama. Warga agama lain keberatan. Sikap Anda sebagai perangkat desa yang paling tepat adalah ....", "opts":[{"t":"Membuka musyawarah untuk mencari lokasi alternatif atau desain yang disepakati semua, mengedepankan kepentingan bersama", "s":5},{"t":"Memfasilitasi dialog dan menawarkan solusi yang mengakomodasi semua pihak", "s":4},{"t":"Memutuskan sepihak berdasarkan suara mayoritas", "s":3},{"t":"Membatalkan pembangunan agar tidak ribut", "s":2},{"t":"Memaksakan pembangunan karena sudah direncanakan", "s":1}], "ex":"Pembangunan fasilitas umum di tengah masyarakat majemuk wajib melalui musyawarah. Keputusan sepihak rawan memicu konflik keyakinan."},
{"id":"TKP-3085", "q":"Seorang pasien berbeda agama dengan Anda menolak ditangani perawat lawan jenis karena keyakinannya. Sebagai petugas kesehatan, tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Menghormati keyakinannya dan mengupayakan penggantian petugas sesuai ketentuan rumah sakit", "s":5},{"t":"Mencarikan solusi penggantian petugas yang memungkinkan secara operasional", "s":4},{"t":"Memintanya menerima petugas yang ada demi kelancaran layanan", "s":3},{"t":"Menolak permintaannya karena dianggap menghambat kerja", "s":2},{"t":"Mengejek keyakinannya sebagai kolot", "s":1}], "ex":"Layanan kesehatan yang humanis menghormati keyakinan pasien sepanjang tidak membahayakan keselamatan. Fleksibilitas operasional adalah solusinya."},
{"id":"TKP-3086", "q":"Warga meminta dispensasi tidak mengikuti upacara bendera karena keyakinannya melarang penghormatan simbol. Sebagai pembina upacara, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menghormati keyakinannya, memberinya peran lain yang sesuai, dan menjelaskan kepada peserta lain tentang penghargaan perbedaan", "s":5},{"t":"Memberikan pengecualian dengan bijak tanpa mempermalukannya di depan umum", "s":4},{"t":"Memaksanya ikut upacara demi kedisiplinan", "s":3},{"t":"Menghukumnya karena dianggap tidak nasionalis", "s":2},{"t":"Mengumumkannya sebagai contoh warga yang tidak cinta tanah air", "s":1}], "ex":"Nasionalisme tidak diukur dari keseragaman ritual. Menghormati keyakinan justru memperkuat persatuan dalam keberagaman."},
{"id":"TKP-3087", "q":"Di grup arisan warga, beredar pesan yang menyudutkan salah satu agama. Sebagai anggota yang juga ASN, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menegur dengan bijak, mengingatkan pentingnya menjaga kerukunan, dan tidak ikut menyebarkan pesan tersebut", "s":5},{"t":"Mengingatkan anggota grup agar tidak menyebarkan ujaran yang menyinggung keyakinan", "s":4},{"t":"Diam saja karena tidak ingin ikut campur", "s":3},{"t":"Ikut menanggapi dengan candaan agar terlihat akrab", "s":2},{"t":"Meneruskan pesan itu ke grup lain", "s":1}], "ex":"ASN adalah teladan kerukunan di masyarakat, termasuk di ruang percakapan informal. Diam terhadap ujaran kebencian berarti membiarkannya tumbuh."},
{"id":"TKP-3088", "q":"Sekolah akan mengadakan perayaan hari besar salah satu agama. Siswa berbeda keyakinan bertanya apakah wajib ikut. Sebagai guru, jawaban Anda yang paling tepat adalah ....", "opts":[{"t":"Menjelaskan bahwa keikutsertaan bersifat sukarela, yang tidak ikut tetap dihargai, dan menjadikannya momen belajar toleransi", "s":5},{"t":"Menyampaikan bahwa siswa boleh memilih ikut atau tidak tanpa paksaan", "s":4},{"t":"Mewajibkan semua siswa ikut demi kebersamaan", "s":3},{"t":"Melarang siswa beda keyakinan hadir di lokasi acara", "s":2},{"t":"Menganggap pertanyaannya sebagai bentuk penolakan yang tidak sopan", "s":1}], "ex":"Perayaan keagamaan di sekolah inklusif bersifat mengajak, bukan memaksa. Toleransi diajarkan lewat penghargaan atas pilihan setiap anak."},
{"id":"TKP-3089", "q":"Warga penganut agama minoritas di desa Anda kesulitan mendapat guru agama untuk anaknya. Sebagai perangkat desa, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Membantu mengusulkan pengadaan guru agama tersebut ke dinas terkait karena itu hak konstitusional anak", "s":5},{"t":"Meneruskan aspirasinya kepada pihak berwenang agar difasilitasi", "s":4},{"t":"Menyarankan anaknya belajar agama secara mandiri di rumah", "s":3},{"t":"Mengabaikan karena jumlahnya sedikit", "s":2},{"t":"Menyarankan mengikuti pelajaran agama mayoritas saja", "s":1}], "ex":"Hak pendidikan agama berlaku bagi semua keyakinan tanpa melihat jumlah penganut. Negara hadir justru untuk yang minoritas."},
{"id":"TKP-3090", "q":"Rekan sekantor berbeda keyakinan dengan Anda sedang berduka karena keluarganya meninggal dengan tata cara agamanya. Sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menyampaikan belasungkawa dengan tulus, menghormati tata cara pemakamannya, dan menawarkan bantuan yang pantas", "s":5},{"t":"Takziah dan memberikan dukungan moral sesuai kepantasan", "s":4},{"t":"Mengirim pesan belasungkawa singkat saja", "s":3},{"t":"Tidak datang karena berbeda keyakinan", "s":2},{"t":"Mengomentari tata cara pemakamannya yang berbeda", "s":1}], "ex":"Duka adalah bahasa universal kemanusiaan. Menghormati tata cara pemakaman beda keyakinan adalah empati tanpa batas agama."},
{"id":"TKP-3091", "q":"Dalam seleksi bantuan usaha, seorang pendaftar mencantumkan keyakinan yang tidak umum di kolom agama. Petugas lain ingin mendiskualifikasinya. Sikap Anda sebagai ketua panitia yang paling tepat adalah ....", "opts":[{"t":"Menolak diskualifikasi dan menegaskan penilaian hanya berdasarkan syarat usaha, bukan keyakinan pendaftar", "s":5},{"t":"Menegaskan bahwa keyakinan bukan kriteria seleksi bantuan", "s":4},{"t":"Memintanya mengganti isian kolom agama", "s":3},{"t":"Mendiskualifikasinya demi menghindari polemik", "s":2},{"t":"Menyetujui diskualifikasi karena keyakinannya janggal", "s":1}], "ex":"Bantuan negara tidak boleh dikaitkan dengan keyakinan penerima. Diskriminasi administratif adalah pelanggaran prinsip keadilan."},
{"id":"TKP-3092", "q":"Warga meminta Anda sebagai ASN menjadi saksi pernikahan beda agama yang sudah sah secara negara. Sebagian rekan menyarankan menolak. Sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Bersedia menjadi saksi secara profesional karena pernikahan tersebut sah menurut hukum negara", "s":5},{"t":"Membantu sebagai saksi dengan tetap menghormati keyakinan kedua mempelai", "s":4},{"t":"Menolak dengan halus karena tidak ingin terlibat", "s":3},{"t":"Menolak dan menasihati mereka agar tidak menikah beda agama", "s":2},{"t":"Menyebarkan kabar pernikahan mereka sebagai bahan gunjingan", "s":1}], "ex":"ASN melayani warga berdasarkan hukum negara, bukan penilaian pribadi atas keyakinan. Profesionalisme berarti memisahkan tugas dari preferensi pribadi."},
{"id":"TKP-3093", "q":"Anak Anda berteman akrab dengan anak tetangga yang berbeda agama dan sering bermain ke rumahnya. Sikap Anda sebagai orang tua yang juga ASN yang paling tepat adalah ....", "opts":[{"t":"Mendukung pertemanan tersebut sebagai pembelajaran toleransi sejak dini, dengan tetap membimbing nilai keyakinan keluarga", "s":5},{"t":"Membiarkan mereka berteman sambil menanamkan sikap saling menghormati", "s":4},{"t":"Membatasi pertemanan agar tidak terlalu akrab", "s":3},{"t":"Melarang anak berteman dengannya", "s":2},{"t":"Menjelek-jelekkan agama tetangga di depan anak", "s":1}], "ex":"Pertemanan lintas agama sejak kecil adalah sekolah toleransi terbaik. Orang tua membimbing keyakinan tanpa menanamkan kebencian."},
{"id":"TKP-3094", "q":"Di tempat ibadah Anda, ada jemaah baru dari suku berbeda yang belum hafal tata cara. Sikap Anda sebagai sesama jemaah yang paling tepat adalah ....", "opts":[{"t":"Menyambutnya dengan ramah dan membimbing tata caranya dengan sabar tanpa menggurui", "s":5},{"t":"Membantunya mengikuti tata cara dengan penjelasan yang bersahabat", "s":4},{"t":"Membiarkannya belajar sendiri dengan memperhatikan jemaah lain", "s":3},{"t":"Menegurnya karena melakukan kesalahan tata cara", "s":2},{"t":"Mengusirnya karena dianggap mengganggu kekhusyukan", "s":1}], "ex":"Rumah ibadah adalah ruang yang merangkul semua suku. Keramahan kepada pendatang baru mencerminkan kemuliaan akhlak beragama."},
{"id":"TKP-3095", "q":"Warga mengeluh pengeras suara rumah ibadah mengganggu istirahatnya. Ia berbeda keyakinan dengan pengelola rumah ibadah. Sebagai aparat, tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Memfasilitasi dialog kedua belah pihak untuk menyepakati pengaturan volume dan jadwal yang saling menghormati", "s":5},{"t":"Menengahi dengan merujuk pada aturan penggunaan pengeras suara rumah ibadah", "s":4},{"t":"Meminta pengelola mematikan pengeras suara sepenuhnya", "s":3},{"t":"Mengabaikan keluhan karena menyangkut ibadah", "s":2},{"t":"Menyalahkan warga yang mengeluh sebagai tidak toleran", "s":1}], "ex":"Ibadah dan hak istirahat warga sama-sama dilindungi. Aturan bersama dan dialog menghasilkan keseimbangan yang adil."},
{"id":"TKP-3096", "q":"Seorang siswa meminta izin tidak mengikuti kegiatan keagamaan sekolah karena keyakinannya berbeda. Wali kelas memaksanya ikut. Sebagai kepala sekolah, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Membela hak siswa, menginstruksikan wali kelas menghormati keyakinannya, dan menyediakan kegiatan alternatif yang bermanfaat", "s":5},{"t":"Menegaskan bahwa tidak ada paksaan dalam kegiatan keagamaan di sekolah", "s":4},{"t":"Membiarkan keputusan wali kelas", "s":3},{"t":"Mendukung wali kelas demi ketertiban", "s":2},{"t":"Menghukum siswa karena dianggap membangkang", "s":1}], "ex":"Kebebasan berkeyakinan peserta didik dilindungi undang-undang. Sekolah yang baik menyediakan ruang bagi semua keyakinan."},
{"id":"TKP-3097", "q":"Dalam acara buka puasa bersama kantor yang dihadiri pegawai lintas keyakinan, panitia lupa menyediakan menu untuk pegawai nonmuslim yang tidak berpuasa. Sebagai ketua panitia, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Segera menyediakan hidangan untuk mereka dan meminta maaf, menegaskan acara kebersamaan milik semua pegawai", "s":5},{"t":"Mengatur agar mereka tetap dapat menikmati jamuan dengan layak", "s":4},{"t":"Meminta mereka menunggu hingga acara selesai", "s":3},{"t":"Menganggapnya hal sepele karena acara bertema puasa", "s":2},{"t":"Menyalahkan mereka karena tidak mengingatkan panitia", "s":1}], "ex":"Acara kebersamaan lintas keyakinan harus inklusif sejak perencanaan. Koreksi cepat atas kelalaian menunjukkan kepedulian yang tulus."},
{"id":"TKP-3098", "q":"Warga beda agama meminta Anda mendoakan kesembuhan keluarganya menurut cara Anda. Sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Mendoakan dengan tulus menurut keyakinan Anda karena doa adalah kebaikan universal", "s":5},{"t":"Menyampaikan doa dan harapan baik untuk kesembuhan keluarganya", "s":4},{"t":"Menolak karena berbeda keyakinan", "s":3},{"t":"Mendoakan asal-asalan agar cepat selesai", "s":2},{"t":"Menertawakan permintaannya", "s":1}], "ex":"Doa lintas agama adalah jembatan kemanusiaan. Ketulusan mendoakan sesama tidak mengurangi kemurnian keyakinan sendiri."},
{"id":"TKP-3099", "q":"Tetangga berbeda keyakinan menitipkan anaknya kepada Anda saat ia beribadah. Sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menerima titipan dengan senang hati dan menjaga anaknya sebaik menjaga anak sendiri", "s":5},{"t":"Membantu menjaga anaknya selama ia beribadah", "s":4},{"t":"Menerima tetapi dengan syarat tertentu", "s":3},{"t":"Menolak karena khawatir terjadi apa-apa", "s":2},{"t":"Menolak dan menyindir keyakinannya yang merepotkan", "s":1}], "ex":"Kepercayaan lintas keyakinan adalah modal sosial yang mahal. Menjaga titipan dengan baik mempererat kerukunan bertetangga."},
{"id":"TKP-3100", "q":"Seorang warga penganut keyakinan lokal ingin mencatatkan pernikahannya di catatan sipil. Petugas ragu karena tidak lazim. Tindakan Anda sebagai atasan petugas yang paling tepat adalah ....", "opts":[{"t":"Menginstruksikan memproses sesuai ketentuan pencatatan sipil karena negara mengakui hak administrasi semua warga", "s":5},{"t":"Memastikan hak pencatatannya dipenuhi sesuai peraturan yang berlaku", "s":4},{"t":"Memintanya melengkapi dengan surat dari tokoh agamanya dulu", "s":3},{"t":"Menunda-nunda prosesnya", "s":2},{"t":"Menolak dengan alasan kepercayaannya tidak diakui", "s":1}], "ex":"Hak administrasi kependudukan melekat pada setiap warga negara. Keyakinan lokal bukan alasan menunda pelayanan negara."},
{"id":"TKP-3101", "q":"Warga masyarakat adat meminta surat keterangan tanah ulayat untuk keperluan sertifikasi. Aturan formal dan hukum adat tampak berbeda. Tindakan Anda sebagai aparat yang paling tepat adalah ....", "opts":[{"t":"Mempelajari kedua aturan, berkonsultasi dengan tokoh adat dan atasan, lalu mencari penyelesaian yang menghormati hak ulayat dalam koridor hukum", "s":5},{"t":"Memfasilitasi dialog antara warga adat dan instansi pertanahan untuk titik temu", "s":4},{"t":"Menolak karena hanya mengakui aturan formal", "s":3},{"t":"Menyuruh warga menyelesaikan sendiri dengan pengacara", "s":2},{"t":"Menganggap tuntutan tanah ulayat sebagai penghambat pembangunan", "s":1}], "ex":"Hak masyarakat adat atas tanah ulayat diakui konstitusi. Penyelesaian terbaik memadukan penghormatan adat dengan kepastian hukum."},
{"id":"TKP-3102", "q":"Seorang bayi dari keluarga adat diberi nama dengan ejaan khas bahasa daerahnya yang tidak ada di sistem komputer dukcapil. Sikap Anda sebagai petugas yang paling tepat adalah ....", "opts":[{"t":"Mencarikan ejaan terdekat yang disetujui keluarga, menjelaskan keterbatasan sistem, dan memastikan nama tercatat dengan hormat", "s":5},{"t":"Berkonsultasi dengan keluarga untuk penulisan yang dapat diterima sistem tanpa mengubah makna nama", "s":4},{"t":"Mengganti namanya sepihak dengan nama yang mudah dieja", "s":3},{"t":"Menolak pencatatan sampai namanya diganti", "s":2},{"t":"Menertawakan nama tersebut di depan keluarga", "s":1}], "ex":"Nama adalah identitas budaya yang sakral bagi keluarga. Keterbatasan teknis diselesaikan dengan musyawarah, bukan pemaksaan."},
{"id":"TKP-3103", "q":"Pembangunan jalan desa akan melewati tanah yang dikeramatkan masyarakat adat setempat. Warga adat menolak. Sebagai perangkat desa, tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Menghentikan sementara rencana, mengajak musyawarah dengan tokoh adat, dan mencari alternatif trase atau ritual adat yang disepakati", "s":5},{"t":"Memfasilitasi perundingan untuk solusi yang menghormati situs keramat", "s":4},{"t":"Melanjutkan pembangunan karena untuk kepentingan umum", "s":3},{"t":"Memaksa dengan aparat keamanan", "s":2},{"t":"Menganggap penolakan mereka sebagai anti-pembangunan", "s":1}], "ex":"Kepentingan umum tidak boleh menginjak martabat budaya masyarakat adat. Musyawarah menghasilkan pembangunan yang berkeadaban."},
{"id":"TKP-3104", "q":"Warga adat ingin menikah secara adat tanpa pencatatan sipil karena menganggap adat sudah cukup. Sebagai petugas, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menghormati pernikahan adatnya sambil menjelaskan pentingnya pencatatan sipil untuk perlindungan hukum keluarga, dan membantu prosesnya", "s":5},{"t":"Menyarankan pencatatan sipil demi kepastian hukum anak dan harta", "s":4},{"t":"Membiarkan tanpa pencatatan karena itu pilihannya", "s":3},{"t":"Menolak mengakui pernikahannya", "s":2},{"t":"Menghina adatnya sebagai ketinggalan zaman", "s":1}], "ex":"Pernikahan adat dihormati, pencatatan negara melindungi. Keduanya bukan lawan melainkan pelengkap bagi kesejahteraan keluarga."},
{"id":"TKP-3105", "q":"Anak dari masyarakat adat terpencil belum memiliki akta kelahiran karena orang tuanya tidak paham prosedur. Yang paling tepat Anda lakukan sebagai petugas adalah ....", "opts":[{"t":"Proaktif mendatangi atau memfasilitasi layanan keliling, membantu pengurusan dengan bahasa yang mudah dipahami", "s":5},{"t":"Memberikan pendampingan penuh hingga akta terbit", "s":4},{"t":"Menunggu mereka datang ke kantor", "s":3},{"t":"Mengenakan denda keterlambatan yang memberatkan", "s":2},{"t":"Mengabaikan karena mereka tinggal jauh", "s":1}], "ex":"Negara wajib jemput bola bagi warga adat terpencil. Akta kelahiran adalah hak dasar anak yang tidak boleh terhambat jarak dan ketidaktahuan."},
{"id":"TKP-3106", "q":"Tradisi adat setempat melarang penebangan pohon tertentu, tetapi perusahaan mengantongi izin resmi. Warga adat protes kepada Anda sebagai camat. Tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Memediasi perusahaan dan warga adat, meninjau ulang izin dari sisi kearifan lokal, dan mencari solusi yang melindungi hutan adat", "s":5},{"t":"Memfasilitasi dialog serta mengusulkan penyesuaian area kerja perusahaan", "s":4},{"t":"Membela perusahaan karena izinnya sah", "s":3},{"t":"Membiarkan warga berdemo tanpa tanggapan", "s":2},{"t":"Menuduh warga adat menghambat investasi", "s":1}], "ex":"Izin formal tidak menghapus hak ulayat dan kearifan lokal. Mediasi yang adil melindungi lingkungan sekaligus kepastian berusaha."},
{"id":"TKP-3107", "q":"Seorang sesepuh adat meninggal dan warga meminta izin menutup jalan desa sehari untuk prosesi adat. Sebagian pengguna jalan keberatan. Sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Memberikan izin terbatas dengan pengaturan lalu lintas alternatif dan sosialisasi kepada pengguna jalan", "s":5},{"t":"Mengizinkan dengan rekayasa lalu lintas agar prosesi dan mobilitas sama-sama berjalan", "s":4},{"t":"Menolak izin demi kelancaran lalu lintas", "s":3},{"t":"Membiarkan penutupan tanpa pengaturan", "s":2},{"t":"Melarang prosesi adat di jalan umum selamanya", "s":1}], "ex":"Penghormatan terakhir bagi sesepuh adat adalah kehormatan komunitas. Pengaturan yang baik membuat adat dan kepentingan umum berjalan beriringan."},
{"id":"TKP-3108", "q":"Warga adat menolak program KB dengan alasan adat menganjurkan banyak anak. Sebagai petugas kesehatan, pendekatan Anda yang paling tepat adalah ....", "opts":[{"t":"Menghormati pandangannya, memberikan edukasi kesehatan reproduksi dengan bahasa budaya setempat, tanpa paksaan", "s":5},{"t":"Berdialog dengan melibatkan tokoh adat tentang kesehatan ibu dan anak", "s":4},{"t":"Memaksa keikutsertaan demi target program", "s":3},{"t":"Mencoretnya dari layanan kesehatan lain sebagai sanksi", "s":2},{"t":"Menyebut adatnya sebagai penyebab kemiskinan", "s":1}], "ex":"Program kesehatan berhasil lewat persuasi budaya, bukan paksaan. Menghormati nilai adat membuka pintu penerimaan program."},
{"id":"TKP-3109", "q":"Anak warga adat tidak bisa mengikuti pelajaran muatan lokal karena materinya tidak mencakup budayanya. Sebagai guru, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Memperkaya materi dengan unsur budaya setempat dan menjadikannya nara sumber kecil tentang adatnya di kelas", "s":5},{"t":"Memberi ruang bagi budaya lokalnya dalam pembelajaran", "s":4},{"t":"Menyuruhnya mengikuti materi yang ada saja", "s":3},{"t":"Mengabaikan karena kurikulum sudah baku", "s":2},{"t":"Menyarankan pindah ke sekolah di daerah asalnya", "s":1}], "ex":"Muatan lokal seharusnya memuliakan budaya setempat. Melibatkan anak sebagai duta budayanya menumbuhkan kebanggaan dan kepercayaan diri."},
{"id":"TKP-3110", "q":"Sengketa waris dalam keluarga adat ingin diselesaikan secara adat, tetapi salah satu pihak menuntut lewat pengadilan. Sebagai tokoh masyarakat yang dimintai saran, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menghormati pilihan jalur hukum sambil menawarkan mediasi adat terlebih dahulu demi keutuhan keluarga", "s":5},{"t":"Menganjurkan musyawarah adat sebagai langkah awal sebelum ke pengadilan", "s":4},{"t":"Mendukung langsung ke pengadilan karena lebih pasti", "s":3},{"t":"Memihak pihak yang sependapat dengan Anda", "s":2},{"t":"Menolak terlibat karena takut disalahkan", "s":1}], "ex":"Penyelesaian adat mengedepankan keharmonisan keluarga. Menawarkan mediasi adat bukan menolak hukum, melainkan menjaga silaturahmi."},
{"id":"TKP-3111", "q":"Warga masyarakat adat Sunda Wiwitan meminta kolom keyakinan di KTP diisi sesuai kepercayaannya. Petugas bingung karena tidak ada di pilihan. Tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Memproses sesuai ketentuan terbaru tentang penghayat kepercayaan karena negara mengakui hak mereka", "s":5},{"t":"Melayani sesuai regulasi yang berlaku bagi penghayat kepercayaan", "s":4},{"t":"Memintanya memilih salah satu agama yang tersedia", "s":3},{"t":"Menolak dan menyuruhnya kembali lain waktu", "s":2},{"t":"Menganggap kepercayaannya bukan keyakinan yang sah", "s":1}], "ex":"Putusan MK mengakui penghayat kepercayaan dalam administrasi kependudukan. Aparat wajib melayani sesuai regulasi tanpa prasangka."},
{"id":"TKP-3112", "q":"Upacara adat panen raya akan menggunakan sebagian dana desa. Sebagian warga non-adat protes. Sebagai kepala desa, keputusan Anda yang paling tepat adalah ....", "opts":[{"t":"Membahas dalam musyawarah desa, memastikan anggaran transparan dan memberi manfaat bagi seluruh warga lintas latar", "s":5},{"t":"Memfasilitasi kesepakatan melalui forum musyawarah yang terbuka", "s":4},{"t":"Memaksakan penggunaan dana karena tradisi", "s":3},{"t":"Membatalkan sepihak demi menghindari protes", "s":2},{"t":"Menggunakan dana diam-diam tanpa musyawarah", "s":1}], "ex":"Dana desa milik seluruh warga. Pelestarian adat yang dibiayai bersama harus disepakati bersama secara transparan."},
{"id":"TKP-3113", "q":"Seorang perawat ditugaskan di daerah adat yang pantang disentuh lawan jenis bukan muhrim. Pasien membutuhkan tindakan segera. Sikap perawat yang paling tepat adalah ....", "opts":[{"t":"Menghormati pantangan adat, segera menghadirkan tenaga kesehatan yang sesuai, sambil memastikan pasien tetap tertangani", "s":5},{"t":"Mencarikan tenaga pengganti yang sesuai adat tanpa menunda pertolongan", "s":4},{"t":"Tetap menangani karena kondisi darurat", "s":3},{"t":"Menunda tindakan sampai keluarga pasien memutuskan", "s":2},{"t":"Menganggap pantangan itu menghambat medis", "s":1}], "ex":"Dalam kondisi darurat, keselamatan pasien utama, tetapi penghormatan adat tetap diupayakan lewat penyesuaian petugas. Keduanya bisa berjalan bersama."},
{"id":"TKP-3114", "q":"Warga adat Baduy meminta tidak difoto saat pengurusan dokumen karena keyakinannya. Petugas membutuhkan foto untuk arsip. Solusi Anda yang paling tepat adalah ....", "opts":[{"t":"Menghormati keyakinannya dan mencari alternatif identifikasi yang disepakati, seperti sidik jari atau keterangan tertulis", "s":5},{"t":"Berdialog mencari pengganti foto yang dapat diterima kedua belah pihak", "s":4},{"t":"Memaksa foto demi kelengkapan arsip", "s":3},{"t":"Menolak melayani tanpa foto", "s":2},{"t":"Memfotonya diam-diam", "s":1}], "ex":"Keyakinan warga adat adalah hak yang dilindungi. Administrasi yang baik selalu punya jalan alternatif yang manusiawi."},
{"id":"TKP-3115", "q":"Generasi muda desa mulai meninggalkan bahasa adatnya. Sebagai perangkat desa yang peduli budaya, langkah Anda yang paling tepat adalah ....", "opts":[{"t":"Menginisiasi program pelestarian bahasa adat bersama tokoh masyarakat, sekolah, dan karang taruna secara sukarela", "s":5},{"t":"Mengajak komunitas membuat kegiatan budaya yang menarik bagi generasi muda", "s":4},{"t":"Mewajibkan penggunaan bahasa adat di kantor desa", "s":3},{"t":"Membiarkan karena itu pilihan zaman", "s":2},{"t":"Menyalahkan orang tua yang tidak mengajarkan", "s":1}], "ex":"Pelestarian bahasa adat tumbuh dari kebanggaan, bukan kewajiban. Program yang melibatkan generasi muda lebih lestari daripada paksaan."},
{"id":"TKP-3116", "q":"Warga adat Dayak ingin mendirikan balai adat di tanah negara yang ia garap turun-temurun. Prosedur perizinan rumit. Bantuan Anda yang paling tepat adalah ....", "opts":[{"t":"Mendampingi pengurusan perizinan langkah demi langkah dan mengoordinasikan dengan instansi terkait", "s":5},{"t":"Membantu memfasilitasi proses perizinan hingga tuntas", "s":4},{"t":"Memberikan brosur prosedur dan membiarkannya mengurus sendiri", "s":3},{"t":"Menolak membantu karena tanahnya berstatus negara", "s":2},{"t":"Menyarankan membangun tanpa izin", "s":1}], "ex":"Aparat adalah pelayan yang mempermudah, bukan mempersulit. Pendampingan aktif menunjukkan negara hadir bagi masyarakat adat."},
{"id":"TKP-3117", "q":"Dalam festival budaya daerah, panitia hanya menampilkan kesenian suku mayoritas. Perwakilan suku minoritas kecewa. Sebagai penasihat acara, saran Anda yang paling tepat adalah ....", "opts":[{"t":"Mengusulkan penjadwalan ulang agar semua suku mendapat panggung yang adil sebagai wujud Bhinneka Tunggal Ika", "s":5},{"t":"Merevisi susunan acara agar keterwakilan budaya lebih berimbang", "s":4},{"t":"Menambah satu slot kecil untuk suku minoritas", "s":3},{"t":"Membiarkan susunan yang ada", "s":2},{"t":"Mengatakan suku minoritas tidak usah menuntut", "s":1}], "ex":"Festival budaya milik semua suku. Keterwakilan yang adil bukan basa-basi, melainkan penghormatan nyata terhadap keberagaman."},
{"id":"TKP-3118", "q":"Seorang warga adat Papua merasa tersinggung dipanggil dengan sebutan yang dianggap merendahkan sukunya oleh petugas. Tindakan Anda sebagai atasan petugas yang paling tepat adalah ....", "opts":[{"t":"Meminta maaf atas nama institusi, membina petugas tentang sensitivitas budaya, dan memastikan pelayanan dilanjutkan dengan hormat", "s":5},{"t":"Menegur petugas dan memastikan kejadian tidak terulang", "s":4},{"t":"Menganggap warga terlalu sensitif", "s":3},{"t":"Membela petugas karena tidak bermaksud buruk", "s":2},{"t":"Mengusir warga yang protes", "s":1}], "ex":"Sebutan yang merendahkan suku adalah luka martabat. Minta maaf dan pembinaan menunjukkan institusi berpihak pada penghormatan budaya."},
{"id":"TKP-3119", "q":"Masyarakat adat memiliki aturan denda adat bagi pelanggar norma kampung. Seorang pendatang melanggar dan menolak membayar denda adat. Sebagai penengah, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menjelaskan kepada pendatang bahwa menghormati norma adat setempat adalah kewajiban tamu, dan memfasilitasi penyelesaian yang disepakati", "s":5},{"t":"Memediasi agar pendatang memahami dan menghormati aturan adat yang berlaku", "s":4},{"t":"Membebaskan pendatang dari denda adat", "s":3},{"t":"Memaksa pendatang membayar tanpa penjelasan", "s":2},{"t":"Mengusir pendatang dari kampung", "s":1}], "ex":"Di mana bumi dipijak, di situ adat dijunjung. Pendatang wajib menghormati norma setempat, diselesaikan lewat dialog bukan paksaan."},
{"id":"TKP-3120", "q":"Warga adat meminta sekolah memasukkan ritual adat dalam kegiatan ekstrakurikuler. Sebagian orang tua murid keberatan. Sebagai kepala sekolah, keputusan Anda yang paling tepat adalah ....", "opts":[{"t":"Membahas dalam komite sekolah, menjadikannya kegiatan pengenalan budaya yang terbuka dan sukarela bagi semua siswa", "s":5},{"t":"Memfasilitasi musyawarah komite untuk format yang disepakati", "s":4},{"t":"Menolak mentah-mentah demi menghindari protes", "s":3},{"t":"Memaksakan sebagai kegiatan wajib", "s":2},{"t":"Mengabaikan usulan tersebut", "s":1}], "ex":"Pengenalan budaya adat di sekolah memperkaya wawasan kebangsaan. Format sukarela dan terbuka merangkul semua keberatan."},
{"id":"TKP-3121", "q":"Petugas sensus kesulitan mendata warga suku terasing yang berpindah-pindah dan curiga pada pendatang. Pendekatan Anda yang paling tepat adalah ....", "opts":[{"t":"Menggandeng tokoh atau pemuka adat setempat sebagai jembatan, datang dengan sopan, dan menjelaskan manfaat pendataan", "s":5},{"t":"Bekerja sama dengan pemuka adat untuk membangun kepercayaan", "s":4},{"t":"Mendata dari kejauhan berdasarkan perkiraan", "s":3},{"t":"Melewatkan mereka dari pendataan", "s":2},{"t":"Melaporkan mereka sebagai warga yang tidak kooperatif", "s":1}], "ex":"Kepercayaan adalah kunci pendataan komunitas terasing. Pendekatan budaya yang sabar menghasilkan data yang akurat dan bermartabat."},
{"id":"TKP-3122", "q":"Seorang seniman adat ingin mematenkan motif ukiran khas sukunya agar tidak diklaim pihak lain. Ia bingung prosedurnya. Bantuan Anda yang paling tepat adalah ....", "opts":[{"t":"Membantu menghubungkannya dengan instansi kekayaan intelektual dan mendampingi proses pendaftaran hingga paham", "s":5},{"t":"Memfasilitasi konsultasi dengan pihak berwenang tentang perlindungan karya budaya", "s":4},{"t":"Memberikan alamat kantor dan membiarkannya mengurus sendiri", "s":3},{"t":"Mengatakan motif adat tidak bisa dipatenkan", "s":2},{"t":"Mengabaikan karena bukan urusan pelayanan Anda", "s":1}], "ex":"Karya budaya adalah kekayaan intelektual komunal yang layak dilindungi negara. Pendampingan aktif mencegah klaim sepihak oleh pihak luar."},
{"id":"TKP-3123", "q":"Warga adat meminta dispensasi menunda pembayaran pajak bumi karena gagal panen akibat ritual adat yang tertunda musimnya. Sikap Anda sebagai petugas pajak yang paling tepat adalah ....", "opts":[{"t":"Menjelaskan mekanisme keringanan/penundaan resmi yang tersedia dan membantu pengajuannya sesuai ketentuan", "s":5},{"t":"Menginformasikan prosedur pengajuan keringanan pajak yang sah", "s":4},{"t":"Menolak karena pajak tidak mengenal adat", "s":3},{"t":"Memberi keringanan diam-diam tanpa prosedur", "s":2},{"t":"Menyita lahannya karena menunggak", "s":1}], "ex":"Kesulitan warga adat disikapi dengan mekanisme resmi yang tersedia, bukan diskresi liar. Aturan yang manusiawi tetap dalam koridor hukum."},
{"id":"TKP-3124", "q":"Dalam rapat adat, perempuan tidak dilibatkan dalam pengambilan keputusan sesuai tradisi setempat. Seorang aktivis memprotes kepada Anda. Sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menghormati otonomi adat sambil membuka dialog perlahan dengan tokoh adat tentang peran perempuan, tanpa memaksa", "s":5},{"t":"Berdialog dengan pemuka adat mengenai pelibatan perempuan secara bertahap", "s":4},{"t":"Memaksa perubahan aturan adat seketika", "s":3},{"t":"Mengabaikan protes aktivis tersebut", "s":2},{"t":"Mendukung penuh tradisi tanpa mau berdialog", "s":1}], "ex":"Perubahan dalam masyarakat adat tumbuh dari dialog internal, bukan tekanan luar. Menghormati otonomi adat sambil membuka ruang percakapan adalah jalan tengah yang bijak."},
{"id":"TKP-3125", "q":"Anak warga adat berprestasi ingin mengikuti lomba tingkat provinsi tetapi terkendala biaya dan restu adat. Dukungan Anda sebagai perangkat desa yang paling tepat adalah ....", "opts":[{"t":"Membantu mencarikan sponsor atau dana desa, berdialog dengan keluarga adatnya, dan mendampingi hingga ia bisa berlomba", "s":5},{"t":"Memfasilitasi dukungan biaya dan restu keluarga secara bersamaan", "s":4},{"t":"Memberi semangat saja tanpa bantuan nyata", "s":3},{"t":"Menyerahkan sepenuhnya pada keluarganya", "s":2},{"t":"Menganggap adatnya menghambat prestasi anak", "s":1}], "ex":"Prestasi anak adat adalah kebanggaan bersama. Dukungan dana dan dialog dengan keluarga membuka jalan tanpa mengorbankan adat."},
{"id":"TKP-3126", "q":"Jam pelayanan loket Anda berbenturan dengan waktu ibadah Jumat. Antrean masih panjang. Sikap Anda sebagai petugas muslim yang paling tepat adalah ....", "opts":[{"t":"Mengatur pergantian dengan rekan nonmuslim secara bergilir dan adil, memastikan loket tetap terlayani", "s":5},{"t":"Berkonsultasi dengan atasan untuk pengaturan jadwal yang menghormati ibadah tanpa menghentikan layanan", "s":4},{"t":"Menutup loket selama ibadah dan meminta warga menunggu", "s":3},{"t":"Tetap melayani sambil menunda ibadah", "s":2},{"t":"Menyalahkan warga yang datang di jam ibadah", "s":1}], "ex":"Ibadah adalah kewajiban, pelayanan adalah amanah. Pengaturan shift yang adil memenuhi keduanya tanpa mengorbankan salah satu."},
{"id":"TKP-3127", "q":"Seorang warga meminta pelayanan KTP diantar ke rumah karena ia sedang menjalani ritual ibadah puasa khusus keyakinannya yang membatasi keluar rumah. Tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Menjelaskan layanan yang tersedia (termasuk layanan keliling/jemput bola bila ada) dan membantu sesuai mekanisme resmi", "s":5},{"t":"Menginformasikan alternatif layanan yang tidak mengharuskan kehadirannya", "s":4},{"t":"Menolak karena semua warga harus datang sendiri", "s":3},{"t":"Mengantar sendiri di luar jam kerja tanpa prosedur", "s":2},{"t":"Menganggap ritualnya mengada-ada", "s":1}], "ex":"Menghormati laku ibadah warga bukan berarti melanggar prosedur. Solusi resmi yang tersedia adalah jalan tengah yang tepat."},
{"id":"TKP-3128", "q":"Rekan kerja Anda meminta izin pulang lebih awal setiap hari selama bulan puasa keyakinannya untuk berbuka bersama keluarga. Sikap Anda sebagai atasannya yang paling tepat adalah ....", "opts":[{"t":"Mengatur penyesuaian jam kerja yang adil dan transparan bagi semua pegawai sesuai aturan kepegawaian", "s":5},{"t":"Mencarikan solusi penjadwalan yang tidak merugikan kinerja tim", "s":4},{"t":"Menolak karena aturan jam kerja sama untuk semua", "s":3},{"t":"Mengizinkan diam-diam tanpa pencatatan", "s":2},{"t":"Menolak dengan alasan keyakinannya tidak resmi", "s":1}], "ex":"Fleksibilitas ibadah dalam koridor aturan kepegawaian adalah wujud penghargaan. Yang penting transparan dan tidak membebani rekan lain."},
{"id":"TKP-3129", "q":"Jadwal ujian CPNS jatuh tepat pada hari besar keagamaan sekelompok peserta. Sebagai panitia, tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Menyediakan jadwal susulan yang sah bagi peserta terdampak sesuai ketentuan, tanpa mengurangi standar seleksi", "s":5},{"t":"Mengusulkan penjadwalan ulang bagi yang berhalangan karena hari besar agama", "s":4},{"t":"Memaksa mengikuti jadwal yang ada", "s":3},{"t":"Mendiskualifikasi yang tidak hadir", "s":2},{"t":"Menganggap hari besar mereka bukan urusan panitia", "s":1}], "ex":"Negara menjamin hak beribadah peserta seleksi. Penjadwalan susulan yang adil menjaga meritokrasi sekaligus toleransi."},
{"id":"TKP-3130", "q":"Pasien rawat inap meminta dijadwalkan operasi di luar waktu ibadahnya. Dokter menilai penundaan berisiko. Sebagai perawat, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menjelaskan risiko medis dengan jujur, menghormati keyakinannya, dan membantu mencari jadwal terbaik bersama dokter dan keluarga", "s":5},{"t":"Memfasilitasi komunikasi antara pasien, keluarga, dan dokter untuk keputusan terbaik", "s":4},{"t":"Memaksa jadwal yang ditentukan dokter", "s":3},{"t":"Menunda operasi sesuai permintaan tanpa menjelaskan risiko", "s":2},{"t":"Menganggap keyakinannya menghambat medis", "s":1}], "ex":"Otonomi pasien atas keyakinannya dihormati, tetapi keputusan medis harus berbasis informasi risiko yang jujur. Dialog tiga pihak menghasilkan keputusan terbaik."},
{"id":"TKP-3131", "q":"Kantor Anda mengadakan rapat penting bertepatan dengan waktu ibadah beberapa pegawai. Sebagai pimpinan rapat, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menyesuaikan jadwal rapat agar tidak berbenturan dengan waktu ibadah, atau memberi jeda ibadah di tengah rapat", "s":5},{"t":"Mengatur ulang waktu rapat dengan mempertimbangkan kewajiban ibadah peserta", "s":4},{"t":"Tetap melaksanakan sesuai jadwal awal", "s":3},{"t":"Meminta yang beribadah memilih antara rapat atau ibadah", "s":2},{"t":"Menganggap ibadah sebagai alasan mangkir rapat", "s":1}], "ex":"Pemimpin yang bijak mengatur agenda dengan memperhatikan kewajiban ibadah bawahannya. Produktivitas tidak harus mengorbankan spiritualitas."},
{"id":"TKP-3132", "q":"Warga lanjut usia meminta pelayanan posyandu dimajukan karena harus mengikuti pengajian rutin keyakinannya. Tindakan Anda sebagai kader yang paling tepat adalah ....", "opts":[{"t":"Mengusulkan penyesuaian jadwal melalui musyawarah warga agar semua nyaman", "s":5},{"t":"Membahas usulan perubahan jadwal dalam forum warga", "s":4},{"t":"Menolak karena jadwal sudah ditetapkan", "s":3},{"t":"Memintanya memilih posyandu atau pengajian", "s":2},{"t":"Menganggap pengajiannya tidak penting", "s":1}], "ex":"Jadwal layanan publik yang responsif terhadap ritme ibadah warga meningkatkan partisipasi. Musyawarah adalah salurannya."},
{"id":"TKP-3133", "q":"Seorang tahanan berbeda keyakinan dengan petugas meminta difasilitasi ibadah sesuai agamanya. Sikap Anda sebagai petugas lapas yang paling tepat adalah ....", "opts":[{"t":"Memfasilitasi ibadahnya sesuai aturan lapas karena hak beribadah melekat pada setiap manusia termasuk warga binaan", "s":5},{"t":"Memberikan akses ibadah yang layak sesuai ketentuan", "s":4},{"t":"Menunda-nunda permintaannya", "s":3},{"t":"Menolak karena statusnya tahanan", "s":2},{"t":"Memaksanya mengikuti ibadah mayoritas", "s":1}], "ex":"Status tahanan tidak menghapus hak beribadah. Negara yang beradab menjamin kebebasan berkeyakinan hingga di balik jeruji."},
{"id":"TKP-3134", "q":"Siswa meminta izin tidak ikut study tour karena biayanya dipakai untuk kegiatan ibadah keyakinannya. Orang tuanya mendukung. Sebagai wali kelas, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menghormati keputusan keluarga, memastikan siswa tetap mendapat tugas pengganti yang bermakna", "s":5},{"t":"Memberikan alternatif tugas agar ia tidak tertinggal pembelajaran", "s":4},{"t":"Memaksanya ikut demi kebersamaan kelas", "s":3},{"t":"Memberinya nilai rendah karena tidak ikut", "s":2},{"t":"Menyindir keyakinannya di depan kelas", "s":1}], "ex":"Prioritas ibadah keluarga adalah hak yang dihormati sekolah. Tugas pengganti memastikan hak belajarnya tetap terpenuhi."},
{"id":"TKP-3135", "q":"Warga meminta surat pengantar untuk cuti ibadah haji/umroh sesuai keyakinannya. Berkasnya kurang satu dokumen. Tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Menjelaskan dokumen yang kurang dengan jelas dan membantu percepatan pengurusannya mengingat waktu keberangkatan", "s":5},{"t":"Memprioritaskan bantuan pengurusan karena sifatnya mendesak dan sakral", "s":4},{"t":"Memproses seperti biasa tanpa percepatan", "s":3},{"t":"Menolak membantu sampai berkas lengkap tanpa penjelasan", "s":2},{"t":"Mempersulit karena iri ia bisa beribadah jauh", "s":1}], "ex":"Ibadah besar seperti haji adalah momen sakral sekali seumur hidup. Pelayanan yang empatik dan solutif adalah bakti aparatur."},
{"id":"TKP-3136", "q":"Di asrama pelatihan, jadwal makan tidak sesuai dengan waktu berbuka ibadah puasa peserta yang berpuasa. Sebagai panitia, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menyesuaikan jadwal konsumsi dan menyediakan takjil, memastikan semua peserta terlayani sesuai keyakinannya", "s":5},{"t":"Mengatur ulang jadwal makan selama bulan puasa", "s":4},{"t":"Meminta peserta berpuasa menyesuaikan diri", "s":3},{"t":"Mengabaikan karena mayoritas tidak berpuasa", "s":2},{"t":"Melarang puasa selama pelatihan", "s":1}], "ex":"Penyelenggara pelatihan wajib akomodatif terhadap ibadah peserta. Penyesuaian jadwal adalah standar layanan yang manusiawi."},
{"id":"TKP-3137", "q":"Seorang pegawai mengajukan cuti untuk ziarah ke tempat suci keyakinannya yang jauh. Kuota cutinya mencukupi tetapi atasannya ragu. Sebagai atasan, keputusan Anda yang paling tepat adalah ....", "opts":[{"t":"Menyetujui cuti sesuai haknya dan mengatur pengganti tugas agar pelayanan tidak terganggu", "s":5},{"t":"Memberikan izin dengan penugasan pelimpahan yang jelas", "s":4},{"t":"Menunda persetujuan sampai pekerjaan sepi", "s":3},{"t":"Menolak karena ziarah bukan kepentingan dinas", "s":2},{"t":"Menolak karena keyakinannya minoritas", "s":1}], "ex":"Cuti ibadah adalah hak pegawai yang dijamin aturan. Menyetujui dengan pengaturan tugas yang baik memenuhi hak tanpa mengorbankan layanan."},
{"id":"TKP-3138", "q":"Warga nonmuslim protes suara pengajian yang disiarkan pengeras suara hingga larut. Pengelola berdalih itu ibadah. Sebagai mediator, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Merujuk pada aturan penggunaan pengeras suara rumah ibadah dan memfasilitasi kesepakatan volume serta batas waktu", "s":5},{"t":"Menengahi dengan pedoman resmi tentang pengeras suara", "s":4},{"t":"Membela pengelola karena itu ibadah", "s":3},{"t":"Melarang seluruh kegiatan pengajian", "s":2},{"t":"Menyalahkan warga yang protes", "s":1}], "ex":"Kebebasan beribadah dibatasi oleh hak orang lain. Aturan pengeras suara adalah titik temu yang adil bagi semua keyakinan."},
{"id":"TKP-3139", "q":"Pasien kritis membutuhkan transfusi darah tetapi keyakinannya melarang. Keluarganya terbagi pendapat. Sebagai dokter, tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Menghormati keyakinan pasien dewasa yang kompeten, menjelaskan alternatif medis yang tersedia, dan mendokumentasikan informed consent", "s":5},{"t":"Menawarkan alternatif pengobatan yang sesuai keyakinannya", "s":4},{"t":"Memaksa transfusi demi menyelamatkan nyawa", "s":3},{"t":"Membiarkan tanpa tindakan medis sama sekali", "s":2},{"t":"Mengikuti suara keluarga yang paling keras", "s":1}], "ex":"Otonomi pasien dewasa atas keyakinannya dihormati dalam etika kedokteran. Dokter wajib menawarkan alternatif terbaik yang tersedia."},
{"id":"TKP-3140", "q":"Sekolah mengadakan pesantren kilat saat libur. Siswa berbeda keyakinan ingin ikut kegiatan positifnya saja. Sebagai panitia, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Membuka kegiatan non-ritual untuk umum sebagai ajang silaturahmi, dengan materi ibadah khusus bagi yang sekeyakinan", "s":5},{"t":"Memisahkan kegiatan umum dan khusus ibadah secara jelas", "s":4},{"t":"Melarang siswa beda keyakinan hadir", "s":3},{"t":"Mewajibkan mengikuti seluruh rangkaian termasuk ibadah", "s":2},{"t":"Membatalkan kegiatan karena dianggap eksklusif", "s":1}], "ex":"Kegiatan keagamaan yang inklusif membuka ruang silaturahmi lintas keyakinan. Pemisahan kegiatan ritual dan umum adalah kuncinya."},
{"id":"TKP-3141", "q":"Warga meminta pelayanan nikah di KUA dimajukan karena menyesuaikan hari baik menurut adat keyakinannya. Antrean sudah terjadwal. Tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Mengupayakan penjadwalan ulang yang memungkinkan tanpa merugikan antrean lain, menghormati hari baiknya", "s":5},{"t":"Mencarikan slot yang memenuhi harapannya sesuai kemungkinan", "s":4},{"t":"Menolak karena jadwal sudah tetap", "s":3},{"t":"Memajukan sepihak dengan mengorbankan antrean lain", "s":2},{"t":"Mengejek kepercayaan hari baiknya", "s":1}], "ex":"Hari baik adalah keyakinan yang patut dihormati. Fleksibilitas penjadwalan yang adil memenuhi harapan tanpa mengorbankan yang lain."},
{"id":"TKP-3142", "q":"Pegawai yang sedang menjalankan ibadah puasa sunah keyakinannya terlihat lemas saat jam kerja. Sebagai rekan, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menawarkan bantuan tugas yang ringan dengan tulus tanpa mengungkit puasanya", "s":5},{"t":"Membantu pekerjaannya secara sukarela", "s":4},{"t":"Membiarkannya karena itu pilihannya berpuasa", "s":3},{"t":"Menyuruhnya membatalkan puasa demi pekerjaan", "s":2},{"t":"Melaporkannya sebagai tidak produktif", "s":1}], "ex":"Solidaritas rekan kerja melampaui perbedaan keyakinan. Bantuan tulus di saat ibadah adalah wujud nyata toleransi."},
{"id":"TKP-3143", "q":"Warga penganut keyakinan lokal meminta jenazah keluarganya dimakamkan dengan tata cara adatnya di pemakaman umum. Sebagian warga menolak. Sebagai aparat, tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Memfasilitasi musyawarah, menegaskan hak setiap warga atas pemakaman yang layak, dan mencari pengaturan yang menghormati semua", "s":5},{"t":"Menengahi dengan memastikan hak pemakamannya terpenuhi", "s":4},{"t":"Melarang tata cara adat di pemakaman umum", "s":3},{"t":"Membiarkan warga menolak tanpa solusi", "s":2},{"t":"Memaksa warga menerima tanpa dialog", "s":1}], "ex":"Penghormatan terakhir adalah hak setiap insan. Dialog menghasilkan pengaturan pemakaman yang bermartabat bagi semua keyakinan."},
{"id":"TKP-3144", "q":"Dalam diklat, peserta berbeda keyakinan meminta menu makanan disesuaikan dengan pantangan agamanya. Panitia menganggap merepotkan. Sikap panitia yang paling tepat adalah ....", "opts":[{"t":"Menyediakan pilihan menu yang mengakomodasi pantangan agama peserta sebagai standar layanan", "s":5},{"t":"Mengoordinasikan dengan penyedia konsumsi untuk menu alternatif", "s":4},{"t":"Meminta peserta membawa bekal sendiri", "s":3},{"t":"Menolak dengan alasan anggaran terbatas", "s":2},{"t":"Menyindir keyakinannya yang merepotkan", "s":1}], "ex":"Pantangan makanan karena keyakinan adalah kebutuhan dasar yang wajib diakomodasi penyelenggara. Inklusivitas dimulai dari hal paling mendasar."},
{"id":"TKP-3145", "q":"Seorang warga ingin mengganti kolom keyakinan di dokumennya setelah berpindah keyakinan. Petugas menolak karena curiga. Tindakan Anda sebagai atasan yang paling tepat adalah ....", "opts":[{"t":"Menginstruksikan memproses sesuai prosedur dan surat pernyataan karena berpindah keyakinan adalah hak warga", "s":5},{"t":"Memastikan hak administrasinya dipenuhi tanpa prasangka", "s":4},{"t":"Meminta pertimbangan tokoh agama lamanya dulu", "s":3},{"t":"Menunda-nunda prosesnya", "s":2},{"t":"Menolak dan menuduhnya mempermainkan agama", "s":1}], "ex":"Kebebasan berkeyakinan termasuk hak berpindah keyakinan. Aparat administrasi tidak berwenang mengadili pilihan spiritual warga."},
{"id":"TKP-3146", "q":"Warga meminta izin menggunakan aula desa untuk perayaan hari besar keyakinannya. Pengurus masjid/gereja setempat keberatan. Sikap Anda sebagai kepala desa yang paling tepat adalah ....", "opts":[{"t":"Memfasilitasi musyawarah penjadwalan penggunaan aula secara bergilir dan adil bagi semua keyakinan", "s":5},{"t":"Mengatur jadwal pakai bersama yang disepakati semua pihak", "s":4},{"t":"Memberikan izin sepihak kepada pemohon", "s":3},{"t":"Menolak semua penggunaan aula untuk kegiatan keagamaan", "s":2},{"t":"Membiarkan mereka berebut sendiri", "s":1}], "ex":"Fasilitas publik milik bersama. Penjadwalan bergilir yang adil adalah wujud nyata sila persatuan dalam keberagaman keyakinan."},
{"id":"TKP-3147", "q":"Anak asuh Anda berbeda keyakinan dengan Anda dan mulai bertanya tentang perbedaan itu. Sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menjelaskan dengan jujur dan santun bahwa perbedaan keyakinan adalah keniscayaan, sambil menanamkan saling menghormati", "s":5},{"t":"Menjawab pertanyaannya secara terbuka tanpa menjelekkan keyakinan mana pun", "s":4},{"t":"Mengalihkan pembicaraan karena sensitif", "s":3},{"t":"Melarangnya bertanya tentang agama", "s":2},{"t":"Menanamkan bahwa keyakinannya salah", "s":1}], "ex":"Rasa ingin tahu anak tentang perbedaan keyakinan adalah momen emas menanamkan toleransi. Kejujuran yang santun membangun kedewasaan."},
{"id":"TKP-3148", "q":"Warga lanjut usia penganut keyakinan minoritas tidak bisa membaca surat panggilan berbahasa Indonesia. Tindakan Anda sebagai petugas yang paling tepat adalah ....", "opts":[{"t":"Mendatanginya atau menjelaskan melalui keluarga/tetangga dengan bahasa yang dipahami, memastikan haknya terpenuhi", "s":5},{"t":"Berupaya menyampaikan informasi hingga benar-benar dipahami", "s":4},{"t":"Menganggapnya sudah menerima surat", "s":3},{"t":"Membatalkan haknya karena tidak merespons", "s":2},{"t":"Mengabaikan karena jumlah penganutnya sedikit", "s":1}], "ex":"Hak warga minoritas tidak berkurang karena keterbatasan bahasa. Negara wajib memastikan informasi sampai dengan cara yang dipahami."},
{"id":"TKP-3149", "q":"Dalam seleksi perangkat desa, kandidat berbeda keyakinan dengan mayoritas warga meraih nilai tertinggi. Ada tekanan menolaknya. Sebagai ketua panitia, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Mempertahankan hasil berdasarkan nilai karena seleksi berbasis merit buta terhadap keyakinan", "s":5},{"t":"Menegaskan kelulusan ditentukan prestasi bukan keyakinan", "s":4},{"t":"Mengulang seleksi dengan kriteria tambahan", "s":3},{"t":"Menggugurkannya demi meredam tekanan", "s":2},{"t":"Membocorkan keyakinannya untuk menjatuhkan", "s":1}], "ex":"Meritokrasi adalah perisai keadilan bagi minoritas keyakinan. Integritas panitia diuji saat mayoritas menekan."},
{"id":"TKP-3150", "q":"Warga meminta doa bersama lintas agama untuk korban bencana di desanya. Sebagian tokoh keberatan mencampur ritual. Sebagai perangkat desa, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Memfasilitasi doa bersama dengan format yang menghormati tiap keyakinan, misal doa bergiliran sesuai agama masing-masing", "s":5},{"t":"Mengusulkan format inklusif yang disepakati semua tokoh", "s":4},{"t":"Membatalkan acara karena tidak sepakat", "s":3},{"t":"Memaksakan satu format ritual", "s":2},{"t":"Mengadakan doa untuk satu agama saja", "s":1}], "ex":"Duka bencana menyatukan semua keyakinan. Format doa bergilir menghormati kekhusyukan tiap agama tanpa mencampuradukkan ritual."},
{"id":"TKP-3151", "q":"Kantor akan libur bersama pada hari besar salah satu agama. Pegawai berbeda keyakinan bertanya apakah wajib ikut perayaannya. Jawaban Anda sebagai atasan yang paling tepat adalah ....", "opts":[{"t":"Menjelaskan libur adalah hak semua, perayaan bersifat sukarela, dan menghargai pilihan tiap pegawai", "s":5},{"t":"Menyampaikan bahwa keikutsertaan perayaan tidak diwajibkan", "s":4},{"t":"Mewajibkan semua ikut demi kekompakan", "s":3},{"t":"Melarang pegawai beda keyakinan mendekati lokasi acara", "s":2},{"t":"Menganggap pertanyaannya sebagai penolakan yang kasar", "s":1}], "ex":"Hari besar keagamaan dirayakan dengan sukacita inklusif. Memaksa partisipasi justru mencederai makna toleransi."},
{"id":"TKP-3152", "q":"Panitia perayaan hari besar agama di kantor hanya mengundang penceramah satu mazhab. Pegawai bermazhab lain kecewa. Sebagai ketua panitia, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Mengevaluasi dan membuka ruang bagi keberagaman mazhab dalam perayaan berikutnya, meminta maaf atas kelalaian", "s":5},{"t":"Mengakui kekuranginklusifan dan memperbaikinya ke depan", "s":4},{"t":"Membiarkan karena sudah terlanjur", "s":3},{"t":"Menyalahkan yang kecewa karena terlalu sensitif", "s":2},{"t":"Melarang perayaan keagamaan di kantor selamanya", "s":1}], "ex":"Perayaan keagamaan institusi harus merangkul seluruh mazhab pegawainya. Evaluasi jujur adalah langkah dewasa."},
{"id":"TKP-3153", "q":"Warga meminta izin pawai hari besar keyakinannya melewati kampung yang mayoritas beda keyakinan. Sebagian warga khawatir. Tindakan Anda sebagai aparat yang paling tepat adalah ....", "opts":[{"t":"Memfasilitasi koordinasi rute, waktu, dan pengamanan dengan melibatkan tokoh kedua belah pihak", "s":5},{"t":"Mengatur teknis pawai agar tertib dan menghormati warga setempat", "s":4},{"t":"Memberikan izin tanpa koordinasi", "s":3},{"t":"Menolak izin demi keamanan", "s":2},{"t":"Membiarkan pawai tanpa pengamanan", "s":1}], "ex":"Ekspresi keagamaan di ruang publik difasilitasi dengan pengaturan yang baik. Koordinasi mencegah gesekan antarwarga."},
{"id":"TKP-3154", "q":"Anak Anda diundang menghadiri perayaan hari besar agama temannya yang berbeda keyakinan. Sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Mengizinkan sebagai pembelajaran toleransi, membekalinya adab menghormati, dan menjemput tepat waktu", "s":5},{"t":"Memberi izin dengan pesan menjaga sikap menghormati", "s":4},{"t":"Melarang karena khawatir terpengaruh", "s":3},{"t":"Mengizinkan tetapi menyuruhnya tidak ikut ritual apa pun dengan kasar", "s":2},{"t":"Menjelek-jelekkan acara temannya", "s":1}], "ex":"Menghadiri perayaan sahabat beda keyakinan adalah pelajaran toleransi hidup. Bekal adab lebih penting daripada larangan."},
{"id":"TKP-3155", "q":"Pedagang kaki lima berbeda keyakinan dengan Anda berjualan di depan rumah ibadah saat hari besar. Warga jemaah protes. Sebagai ketua RT, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Memediasi penataan lokasi dagang sementara yang tidak mengganggu ibadah dan tetap memberi ruang usaha", "s":5},{"t":"Mencarikan solusi lokasi alternatif yang disepakati", "s":4},{"t":"Mengusir pedagang selama hari besar", "s":3},{"t":"Membiarkan pedagang berjualan di depan pintu masuk", "s":2},{"t":"Melarangnya berdagang di kampung selamanya", "s":1}], "ex":"Hak beribadah dan hak mencari nafkah sama-sama mulia. Penataan yang adil menyelesaikan tanpa mengorbankan salah satu."},
{"id":"TKP-3156", "q":"Sekolah Anda akan mengadakan lomba menghias kelas bertema hari besar keagamaan. Kelas dengan siswa majemuk bingung memilih tema. Saran Anda sebagai guru yang paling tepat adalah ....", "opts":[{"t":"Mengusulkan tema kebersamaan dalam keberagaman yang bisa diisi semua keyakinan siswa", "s":5},{"t":"Menyarankan tema inklusif yang merangkul semua siswa", "s":4},{"t":"Memaksakan tema satu agama", "s":3},{"t":"Menarik kelas dari lomba", "s":2},{"t":"Membiarkan siswa bertengkar memilih tema", "s":1}], "ex":"Kreativitas keberagaman adalah tema pemersatu. Semua keyakinan siswa mendapat ruang dalam satu karya bersama."},
{"id":"TKP-3157", "q":"Warga meminta dispensasi membayar PBB setelah hari besar keyakinannya karena dananya terpakai untuk perayaan. Sikap Anda sebagai petugas yang paling tepat adalah ....", "opts":[{"t":"Menjelaskan mekanisme penundaan resmi bila tersedia dan membantu pengajuannya", "s":5},{"t":"Menginformasikan prosedur keringanan yang sah", "s":4},{"t":"Menolak mentah-mentah", "s":3},{"t":"Memberi dispensasi diam-diam", "s":2},{"t":"Menyita asetnya segera", "s":1}], "ex":"Kesulitan ekonomi pasca perayaan keyakinan disikapi lewat mekanisme resmi. Empati tetap dalam koridor aturan."},
{"id":"TKP-3158", "q":"Dalam rapat, rekan mengusulkan anggaran perayaan hari besar hanya untuk agama mayoritas pegawai. Sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Mengusulkan anggaran yang proporsional dan adil bagi perayaan semua keyakinan pegawai", "s":5},{"t":"Menegaskan asas keadilan dalam penganggaran kegiatan keagamaan", "s":4},{"t":"Menyetujui usulan tersebut", "s":3},{"t":"Mengusulkan menghapus semua anggaran perayaan", "s":2},{"t":"Mendukung dengan syarat agamanya didahulukan", "s":1}], "ex":"Anggaran institusi milik semua pegawai lintas keyakinan. Keadilan distributif adalah wujud nyata Bhinneka Tunggal Ika."},
{"id":"TKP-3159", "q":"Tetangga berbeda keyakinan mengirimkan parsel hari besar agamanya kepada Anda. Sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menerima dengan gembira dan berterima kasih, serta membalas kebaikannya di hari besar Anda", "s":5},{"t":"Menerima dengan hangat sebagai tanda persaudaraan", "s":4},{"t":"Menolak dengan halus karena berbeda keyakinan", "s":3},{"t":"Menerima tetapi membuangnya", "s":2},{"t":"Menolak dengan kasar dan menyindir", "s":1}], "ex":"Parsel hari besar adalah bahasa kasih lintas keyakinan. Menerima dengan gembira mempererat tali persaudaraan bertetangga."},
{"id":"TKP-3160", "q":"Warga mengeluh toa masjid/gereja/kuil membangunkan bayinya setiap subuh/pagi. Ia berbeda keyakinan. Sebagai penengah, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Memfasilitasi dialog dengan pengurus rumah ibadah merujuk aturan pengeras suara yang berlaku", "s":5},{"t":"Menengahi berdasarkan regulasi yang adil bagi semua", "s":4},{"t":"Menyuruh warga pindah rumah", "s":3},{"t":"Meminta rumah ibadah menghentikan seluruh aktivitas", "s":2},{"t":"Mengabaikan keluhan tersebut", "s":1}], "ex":"Aturan pengeras suara rumah ibadah dibuat untuk keseimbangan semua pihak. Dialog berbasis regulasi lebih adil daripada emosi."},
{"id":"TKP-3161", "q":"Siswa berbeda keyakinan dengan Anda menjadi ketua panitia acara keagamaan sekolah. Ia meminta saran Anda. Sikap Anda sebagai guru yang paling tepat adalah ....", "opts":[{"t":"Membimbing dengan profesional dan mendukung kesuksesannya tanpa mencampuri keyakinannya", "s":5},{"t":"Memberikan arahan organisasional yang dibutuhkan", "s":4},{"t":"Menolak membantu karena beda keyakinan", "s":3},{"t":"Mengambil alih kepanitiaan", "s":2},{"t":"Menyabotase acaranya", "s":1}], "ex":"Profesionalisme guru melampaui sekat keyakinan. Mendukung anak didik berorganisasi adalah amanah pendidikan."},
{"id":"TKP-3162", "q":"Kantor Anda menerima tamu asing dengan keyakinan yang tidak dikenal. Ia meminta ruang untuk beribadah. Tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Menyediakan ruang yang layak dan menghormati privasinya beribadah", "s":5},{"t":"Memfasilitasi kebutuhan ibadahnya dengan ramah", "s":4},{"t":"Menolak karena keyakinannya asing", "s":3},{"t":"Menginterogasinya tentang keyakinannya", "s":2},{"t":"Mengusirnya dari kantor", "s":1}], "ex":"Keramahan Indonesia diuji pada tamu yang paling berbeda. Memfasilitasi ibadah tamu adalah diplomasi budaya terbaik."},
{"id":"TKP-3163", "q":"Warga meminta KTP-nya dicetak ulang karena kolom keyakinan salah tulis oleh petugas. Petugas enggan memperbaiki. Tindakan Anda sebagai atasan yang paling tepat adalah ....", "opts":[{"t":"Menginstruksikan perbaikan segera karena kesalahan administrasi adalah tanggung jawab institusi", "s":5},{"t":"Memastikan koreksi dilakukan tanpa membebani warga", "s":4},{"t":"Meminta warga mengurus dari awal lagi", "s":3},{"t":"Membiarkan kesalahan tersebut", "s":2},{"t":"Menyalahkan warga yang tidak memeriksa", "s":1}], "ex":"Kesalahan petugas wajib diperbaiki institusi tanpa membebani warga. Kolom keyakinan adalah data sakral identitas warga."},
{"id":"TKP-3164", "q":"Dalam pelatihan bela negara, peserta berbeda keyakinan meminta waktu ibadah di sela materi padat. Instruktur keberatan. Sikap instruktur yang paling tepat adalah ....", "opts":[{"t":"Menyisipkan jeda ibadah dalam jadwal karena bela negara dan ibadah sama-sama kewajiban mulia", "s":5},{"t":"Menyesuaikan jadwal dengan memperhatikan waktu ibadah peserta", "s":4},{"t":"Menolak demi kelancaran materi", "s":3},{"t":"Menghukum yang meminta jeda", "s":2},{"t":"Menganggap permintaan itu melemahkan kedisiplinan", "s":1}], "ex":"Bela negara yang sejati menghormati keyakinan pembelanya. Jeda ibadah tidak mengurangi kedisiplinan, justru menguatkan moral."},
{"id":"TKP-3165", "q":"Warga penganut keyakinan lokal ingin anaknya mendapat pelajaran budi pekerti, bukan agama tertentu. Sekolah bingung. Sikap dinas pendidikan yang paling tepat adalah ....", "opts":[{"t":"Memfasilitasi layanan pendidikan kepercayaan sesuai regulasi karena itu hak konstitusional anak", "s":5},{"t":"Mengupayakan pemenuhan hak pendidikan kepercayaannya", "s":4},{"t":"Memaksanya memilih salah satu agama", "s":3},{"t":"Membiarkannya tanpa pelajaran apa pun", "s":2},{"t":"Mengeluarkan anak dari sekolah", "s":1}], "ex":"Anak penghayat kepercayaan berhak atas pendidikan keyakinannya. Negara memfasilitasi, bukan memaksa pilihan."},
{"id":"TKP-3166", "q":"Tetangga mengadakan pengajian rutin dengan pengeras suara setiap malam. Anda berbeda keyakinan dan butuh istirahat. Langkah Anda yang paling tepat adalah ....", "opts":[{"t":"Berkomunikasi baik-baik, menyampaikan kebutuhan istirahat, dan mencari kesepakatan volume serta durasi", "s":5},{"t":"Berdialog sopan untuk pengaturan yang saling nyaman", "s":4},{"t":"Melapor ke aparat tanpa berbicara dulu", "s":3},{"t":"Mendiamkan sambil memendam kesal", "s":2},{"t":"Memaki tetangga karena merasa terganggu", "s":1}], "ex":"Ibadah rutin tetangga dan hak istirahat Anda sama-sama sah. Komunikasi langsung yang santun adalah jalan keluar terbaik."},
{"id":"TKP-3167", "q":"Seorang mualaf meminta bimbingan administrasi kependudukan setelah berpindah keyakinan. Ia takut didiskriminasi. Sikap Anda sebagai petugas yang paling tepat adalah ....", "opts":[{"t":"Melayani dengan ramah dan profesional, menjamin kerahasiaan datanya, tanpa menghakimi pilihannya", "s":5},{"t":"Memproses keperluannya secara normal dan menghormati privasinya", "s":4},{"t":"Menanyai alasannya berpindah keyakinan", "s":3},{"t":"Mempersulit prosesnya", "s":2},{"t":"Menyebarkan kabar perpindahannya", "s":1}], "ex":"Keputusan spiritual warga adalah privasi yang dilindungi. Pelayanan yang ramah tanpa prasangka adalah standar aparatur."},
{"id":"TKP-3168", "q":"Di desa wisata budaya, wisatawan asing ingin menyaksikan ritual adat yang sakral bagi warga. Sebagian warga keberatan. Sebagai pengelola, keputusan Anda yang paling tepat adalah ....", "opts":[{"t":"Membahas dengan tokoh adat batasan yang boleh disaksikan, menjadikan wisata edukasi yang menghormati kesakralan", "s":5},{"t":"Memfasilitasi kesepakatan antara kebutuhan wisata dan kesakralan adat", "s":4},{"t":"Membuka bebas demi pendapatan desa", "s":3},{"t":"Menutup total akses wisatawan", "s":2},{"t":"Mengabaikan keberatan warga", "s":1}], "ex":"Pariwisata budaya lestari bila kesakralan adat dijaga. Batasan yang disepakati melindungi martabat sekaligus ekonomi warga."},
{"id":"TKP-3169", "q":"Warga berbeda keyakinan dengan Anda menjadi donatur pembangunan rumah ibadah Anda. Sebagian jemaah menolak sumbangannya. Sikap Anda sebagai pengurus yang paling tepat adalah ....", "opts":[{"t":"Menerima dengan terima kasih sebagai wujud persaudaraan kemanusiaan, menjelaskan kepada jemaah makna toleransi", "s":5},{"t":"Menghargai ketulusannya dan menjadikannya teladan kerukunan", "s":4},{"t":"Menolak demi menjaga kemurnian dana", "s":3},{"t":"Menerima diam-diam tanpa pemberitahuan", "s":2},{"t":"Menghinanya karena berbeda keyakinan", "s":1}], "ex":"Kebaikan tidak mengenal sekat keyakinan. Menerima uluran tangan lintas agama adalah dakwah toleransi yang paling indah."},
{"id":"TKP-3170", "q":"Anak didik Anda bertanya mengapa ada banyak agama di Indonesia. Jawaban Anda sebagai guru yang paling tepat adalah ....", "opts":[{"t":"Menjelaskan dengan bijak bahwa keberagaman keyakinan adalah anugerah, dan tugas kita saling menghormati", "s":5},{"t":"Memberikan pemahaman tentang indahnya keberagaman Indonesia", "s":4},{"t":"Menyuruhnya tidak bertanya hal sensitif", "s":3},{"t":"Menjawab bahwa hanya satu agama yang benar", "s":2},{"t":"Mengabaikan pertanyaannya", "s":1}], "ex":"Rasa ingin tahu anak tentang keberagaman adalah pintu masuk pendidikan toleransi. Jawaban bijak menanamkan penghargaan seumur hidup."},
{"id":"TKP-3171", "q":"Warga meminta surat keterangan belum menikah untuk pernikahan beda keyakinan yang sah secara negara. Petugas ragu. Tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Memproses sesuai prosedur administrasi karena negara mengakui pernikahan yang sah menurut hukum", "s":5},{"t":"Melayani berdasarkan kelengkapan dokumen, bukan penilaian keyakinan", "s":4},{"t":"Menolak karena tidak setuju pernikahan beda keyakinan", "s":3},{"t":"Mempersulit dengan syarat tambahan", "s":2},{"t":"Menyebarkan kabar pernikahannya", "s":1}], "ex":"Administrasi negara berjalan di atas hukum, bukan selera pribadi petugas. Profesionalisme berarti melayani semua yang sah."},
{"id":"TKP-3172", "q":"Dalam bakti sosial lintas agama, panitia bingung menentukan doa pembuka. Saran Anda yang paling tepat adalah ....", "opts":[{"t":"Mengusulkan doa bergiliran atau momen hening bersama yang menghormati semua keyakinan", "s":5},{"t":"Menyarankan format inklusif yang disepakati semua unsur", "s":4},{"t":"Memaksakan doa satu agama", "s":3},{"t":"Menghilangkan sesi doa sepenuhnya", "s":2},{"t":"Membiarkan panitia bertengkar", "s":1}], "ex":"Kebaikan sosial menyatukan semua keyakinan. Format doa inklusif menunjukkan kematangan beragama dalam keberagaman."},
{"id":"TKP-3173", "q":"Seorang lansia penganut keyakinan minoritas meninggal dan keluarganya bingung mengurus surat kematian. Bantuan Anda yang paling tepat adalah ....", "opts":[{"t":"Membantu pengurusan surat kematian dengan empati penuh seperti kepada warga lainnya", "s":5},{"t":"Mendampingi keluarga hingga surat terbit", "s":4},{"t":"Meminta keluarga mengurus sendiri", "s":3},{"t":"Menunda karena keyakinannya tidak umum", "s":2},{"t":"Menolak membantu", "s":1}], "ex":"Duka tidak mengenal mayoritas-minoritas keyakinan. Pelayanan empati di saat berduka adalah kemanusiaan tertinggi aparatur."},
{"id":"TKP-3174", "q":"Warga protes pembangunan menara rumah ibadah yang dianggap terlalu tinggi di lingkungannya. Ia berbeda keyakinan. Sebagai aparat, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Memeriksa kesesuaian IMB dan regulasi, memfasilitasi dialog antara pengelola dan warga yang keberatan", "s":5},{"t":"Menegakkan aturan perizinan secara objektif dan menengahi kedua pihak", "s":4},{"t":"Memerintahkan pembongkaran demi meredam protes", "s":3},{"t":"Membiarkan pembangunan tanpa memeriksa izin", "s":2},{"t":"Memihak warga yang protes tanpa dasar aturan", "s":1}], "ex":"Sengketa fisik rumah ibadah diselesaikan dengan aturan perizinan yang objektif, bukan sentimen keyakinan. Dialog melengkapi penegakan aturan."},
{"id":"TKP-3175", "q":"Siswa baru berbeda keyakinan dengan mayoritas terlihat canggung mengikuti upacara bendera yang diawali doa. Sebagai pembina, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Memastikan ia merasa diterima, menjelaskan ia boleh berdoa menurut keyakinannya dalam hening", "s":5},{"t":"Memberinya ruang menjalankan keyakinannya dengan nyaman", "s":4},{"t":"Memaksanya mengikuti tata cara mayoritas", "s":3},{"t":"Mengeluarkannya dari barisan upacara", "s":2},{"t":"Menegurnya di depan peserta lain", "s":1}], "ex":"Upacara bendera adalah milik semua keyakinan. Memberi ruang berdoa menurut keyakinan masing-masing adalah nasionalisme yang toleran."},
{"id":"TKP-3176", "q":"Pegawai meminta izin tidak masuk karena harus memimpin upacara adat kematian di kampungnya sebagai pemangku adat. Tugasnya sedang banyak. Sebagai atasan, keputusan Anda yang paling tepat adalah ....", "opts":[{"t":"Memberikan izin dengan pengaturan pelimpahan tugas, menghormati peran adatnya yang tidak tergantikan", "s":5},{"t":"Menyetujui izin dengan memastikan pekerjaannya ter-cover", "s":4},{"t":"Menolak karena tugas sedang menumpuk", "s":3},{"t":"Memberi izin tetapi memotong tunjangannya", "s":2},{"t":"Menolak dengan alasan adat bukan urusan dinas", "s":1}], "ex":"Peran adat yang tidak tergantikan layak mendapat dispensasi bijak. Pengaturan tugas yang baik menjaga layanan tetap berjalan."},
{"id":"TKP-3177", "q":"Kantor akan direnovasi dan menurut adat setempat perlu ritual tolak bala sebelum pembongkaran. Sebagian pegawai keberatan. Sikap Anda sebagai pimpinan yang paling tepat adalah ....", "opts":[{"t":"Memfasilitasi musyawarah, melaksanakan ritual secara sederhana dan sukarela bagi yang meyakini, tanpa paksaan", "s":5},{"t":"Mengakomodasi ritual secara inklusif dan tidak memaksa", "s":4},{"t":"Melarang ritual karena tidak sesuai aturan dinas", "s":3},{"t":"Mewajibkan semua pegawai ikut ritual", "s":2},{"t":"Mengejek kepercayaan adat tersebut", "s":1}], "ex":"Kearifan lokal dihormati tanpa memaksa keyakinan. Format sukarela merangkul yang meyakini dan yang tidak."},
{"id":"TKP-3178", "q":"Warga adat meminta prosesi kirab budayanya melintasi jalan protokol saat jam sibuk. Dinas perhubungan keberatan. Sebagai camat, tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Memediasi penjadwalan ulang di luar jam sibuk dengan pengamanan dan rekayasa lalu lintas yang memadai", "s":5},{"t":"Mencarikan waktu dan rute alternatif yang disepakati", "s":4},{"t":"Memberikan izin sesuai permintaan warga", "s":3},{"t":"Menolak mentah-mentah", "s":2},{"t":"Membiarkan kirab tanpa izin dan pengamanan", "s":1}], "ex":"Ekspresi budaya di ruang publik difasilitasi dengan manajemen yang baik. Penjadwalan cerdas menghindari benturan kepentingan."},
{"id":"TKP-3179", "q":"Pegawai perempuan bersuku tertentu meminta dispensasi pakaian dinas karena alasan adat. Aturan pakaian dinas cukup kaku. Sikap Anda sebagai atasan yang paling tepat adalah ....", "opts":[{"t":"Mengkaji aturan yang berlaku, berkonsultasi ke atas, dan mengupayakan penyesuaian yang menghormati adatnya", "s":5},{"t":"Meneruskan aspirasinya melalui jalur resmi kepegawaian", "s":4},{"t":"Menolak karena aturan tidak mengenal pengecualian", "s":3},{"t":"Memberi izin diam-diam", "s":2},{"t":"Menegurnya karena dianggap tidak disiplin", "s":1}], "ex":"Identitas adat dalam berpakaian adalah ekspresi budaya yang sah. Aspirasi disalurkan lewat mekanisme resmi, bukan ditolak mentah."},
{"id":"TKP-3180", "q":"Tradisi adat melarang warga bekerja pada hari tertentu, tetapi proyek desa dikejar tenggat. Sebagai kepala desa, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menghormati hari pantang adat dan menyesuaikan jadwal proyek dengan musyawarah warga", "s":5},{"t":"Menjadwalkan ulang pekerjaan menghindari hari pantangan", "s":4},{"t":"Memaksa bekerja demi tenggat", "s":3},{"t":"Membayar denda adat dari kas desa diam-diam", "s":2},{"t":"Menganggap tradisi itu menghambat pembangunan", "s":1}], "ex":"Tenggat proyek tidak boleh menginjak keyakinan adat. Penjadwalan yang menghormati tradisi justru melancarkan partisipasi warga."},
{"id":"TKP-3181", "q":"Seorang bidan diminta membantu persalinan dengan tata cara adat tertentu oleh keluarga. Prosedur medis dan adat sedikit berbeda. Sikap bidan yang paling tepat adalah ....", "opts":[{"t":"Mengakomodasi tata cara adat yang tidak membahayakan medis sambil memastikan keselamatan ibu dan bayi sesuai standar", "s":5},{"t":"Memadukan penghormatan adat dengan protokol kesehatan", "s":4},{"t":"Menolak seluruh tata cara adat", "s":3},{"t":"Mengikuti adat sepenuhnya mengabaikan medis", "s":2},{"t":"Mengejek kepercayaan keluarga", "s":1}], "ex":"Keselamatan medis adalah batas, di dalamnya adat dihormati seluas mungkin. Kolaborasi dukun beranak dan bidan adalah praktik terbaik."},
{"id":"TKP-3182", "q":"Warga adat ingin mengadakan ritual di sumber mata air yang menjadi PDAM desa. Khawatir mencemari air. Sebagai pengelola, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Berdialog dengan tokoh adat mencari titik ritual yang tidak mencemari sumber air, dengan solusi teknis yang disepakati", "s":5},{"t":"Memfasilitasi kesepakatan lokasi dan tata cara yang aman bagi air baku", "s":4},{"t":"Melarang total ritual di kawasan sumber air", "s":3},{"t":"Membiarkan tanpa pengaturan", "s":2},{"t":"Menutup akses warga adat ke sumber air", "s":1}], "ex":"Kesakralan adat dan kesehatan publik sama-sama penting. Solusi teknis hasil musyawarah melindungi keduanya."},
{"id":"TKP-3183", "q":"Pegawai baru dari suku berbeda belum paham etika adat setempat dan tanpa sengaja menyinggung warga. Sebagai atasannya, tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Membimbingnya memahami adat setempat, memfasilitasi permintaan maaf yang tulus kepada warga", "s":5},{"t":"Memberikan pembinaan budaya lokal dan mendampinginya meminta maaf", "s":4},{"t":"Membiarkannya belajar sendiri dari pengalaman", "s":3},{"t":"Menghukumnya karena mencoreng institusi", "s":2},{"t":"Memutasi ke daerah asalnya", "s":1}], "ex":"Ketidaktahuan budaya bukan kesalahan moral. Pembinaan dan permintaan maaf yang tulus memulihkan hubungan dengan warga."},
{"id":"TKP-3184", "q":"Dalam seleksi tilik, peserta dari suku tertentu selalu gagal di tahap wawancara meski nilai tulis tinggi. Ia menduga pewawancara bias suku. Sebagai ketua panitia, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Mengevaluasi objektivitas pewawancara, memastikan rubrik penilaian buta suku, dan membuka ruang sanggah yang transparan", "s":5},{"t":"Meninjau ulang proses wawancara demi keadilan", "s":4},{"t":"Menyatakan hasil sudah final", "s":3},{"t":"Menuduhnya tidak legawa kalah", "s":2},{"t":"Membocorkan identitas pewawancara untuk diintimidasi", "s":1}], "ex":"Dugaan bias suku dalam seleksi harus ditanggapi dengan audit objektivitas, bukan pembelaan diri. Keadilan prosedural memulihkan kepercayaan."},
{"id":"TKP-3185", "q":"Warga adat meminta anaknya dibebaskan dari pelajaran tertentu yang bertentangan dengan adatnya. Sekolah bingung. Sikap dinas yang paling tepat adalah ....", "opts":[{"t":"Mengkaji kurikulum, memberikan dispensasi bijak untuk materi yang bertentangan, dengan tugas pengganti yang setara", "s":5},{"t":"Mencarikan solusi pembelajaran alternatif yang menghormati adatnya", "s":4},{"t":"Menolak karena kurikulum nasional seragam", "s":3},{"t":"Mengeluarkan anak dari sekolah", "s":2},{"t":"Memaksa mengikuti semua pelajaran", "s":1}], "ex":"Hak pendidikan dan penghormatan adat bisa berjalan beriringan lewat dispensasi bijak dan tugas pengganti yang bermakna."},
{"id":"TKP-3186", "q":"Proyek wisata akan membangun di atas situs ritual adat. Investor sudah mengantongi izin. Warga adat mengadu kepada Anda. Tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Memfasilitasi perundingan ulang, mengusulkan relokasi atau zona penyangga situs ritual, dan meninjau izin dari sisi sosial budaya", "s":5},{"t":"Memediasi agar situs ritual tetap terlindungi", "s":4},{"t":"Mendukung investor karena izinnya sah", "s":3},{"t":"Mengabaikan aduan warga", "s":2},{"t":"Menggerakkan warga menolak dengan kekerasan", "s":1}], "ex":"Izin investasi tidak menghapus hak budaya masyarakat adat. Peninjauan sosial budaya adalah bagian dari perizinan yang berkeadilan."},
{"id":"TKP-3187", "q":"Seorang jaksa berbeda suku dengan terdakwa dituduh tidak objektif oleh keluarga terdakwa. Sikap jaksa yang paling tepat adalah ....", "opts":[{"t":"Menegakkan profesionalitas, mendasarkan tuntutan murni pada fakta dan hukum, serta terbuka pada pengawasan", "s":5},{"t":"Bekerja objektif dan transparan agar tidak ada prasangka", "s":4},{"t":"Mundur dari perkara karena dituduh", "s":3},{"t":"Memperberat tuntutan karena tersinggung", "s":2},{"t":"Meringankan karena takut dituduh bias", "s":1}], "ex":"Aparat penegak hukum menjawab tuduhan bias suku dengan profesionalitas yang konsisten. Keadilan buta terhadap suku pelaku maupun korban."},
{"id":"TKP-3188", "q":"Warga adat meminta surat keterangan miskin dengan data yang tidak sesuai fakta demi mendapat bantuan. Ia berdalih adat mengajarkan saling membantu. Sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menolak dengan halus sambil menjelaskan bahwa kejujuran data melindungi warga yang benar-benar membutuhkan, termasuk dari sukunya", "s":5},{"t":"Menegaskan verifikasi data berlaku adil untuk semua", "s":4},{"t":"Memberikan surat karena kasihan", "s":3},{"t":"Melaporkannya sebagai penipu", "s":2},{"t":"Menghinanya sebagai pembohong", "s":1}], "ex":"Integritas data bantuan tidak bisa ditawar dengan dalih apa pun. Penolakan yang halus disertai penjelasan melindungi yang berhak."},
{"id":"TKP-3189", "q":"Dalam festival kuliner daerah, stand makanan suku minoritas sepi pengunjung karena stereotip rasa. Sebagai panitia, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Mempromosikan semua stand secara adil dan mengedukasi pengunjung tentang kekayaan kuliner tiap suku", "s":5},{"t":"Memberikan eksposur berimbang bagi seluruh peserta", "s":4},{"t":"Membiarkan mekanisme pasar", "s":3},{"t":"Menutup stand yang sepi", "s":2},{"t":"Ikut menyebarkan stereotip rasanya", "s":1}], "ex":"Panitia festival adalah duta keberagaman kuliner. Promosi adil membantu melestarikan citarasa suku minoritas."},
{"id":"TKP-3190", "q":"Pegawai dimutasi ke daerah dengan adat yang sangat berbeda dan merasa tertekan. Sebagai atasan barunya, dukungan Anda yang paling tepat adalah ....", "opts":[{"t":"Menyambutnya hangat, mengenalkannya pada budaya setempat secara bertahap, dan memberinya waktu adaptasi yang wajar", "s":5},{"t":"Membantu proses adaptasinya dengan pendampingan", "s":4},{"t":"Menuntut langsung berkinerja penuh", "s":3},{"t":"Menganggapnya manja", "s":2},{"t":"Mengusulkan mutasi balik", "s":1}], "ex":"Adaptasi lintas budaya butuh waktu dan dukungan. Pimpinan yang empatik mempercepat integrasi pegawai mutasi."},
{"id":"TKP-3191", "q":"Warga adat menolak vaksinasi dengan alasan kepercayaan turun-temurun. Cakupan imunisasi desa rendah. Pendekatan Anda sebagai petugas kesehatan yang paling tepat adalah ....", "opts":[{"t":"Berdialog sabar dengan tokoh adat, menjelaskan manfaat vaksin dengan bahasa budaya, tanpa paksaan", "s":5},{"t":"Melibatkan pemuka adat sebagai teladan vaksinasi", "s":4},{"t":"Memaksa vaksinasi massal", "s":3},{"t":"Mencabut layanan kesehatan lain sebagai tekanan", "s":2},{"t":"Menyebut kepercayaannya sebagai kebodohan", "s":1}], "ex":"Kepercayaan kesehatan dibangun lewat dialog budaya, bukan paksaan. Tokoh adat yang divaksin adalah persuasi terkuat."},
{"id":"TKP-3192", "q":"Anak warga adat tidak naik kelas karena nilai pelajaran yang bertentangan dengan adatnya rendah. Orang tua protes. Sebagai kepala sekolah, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Meninjau holistik prestasinya, mempertimbangkan dispensasi yang adil, dan mencari solusi pendidikan terbaik bagi anak", "s":5},{"t":"Mengevaluasi ulang dengan memperhatikan konteks budayanya", "s":4},{"t":"Menolak protes karena nilai sudah final", "s":3},{"t":"Meluluskan begitu saja demi meredam protes", "s":2},{"t":"Menyalahkan adatnya sebagai penghambat belajar", "s":1}], "ex":"Penilaian pendidikan harus adil dan kontekstual. Tinjauan holistik melindungi hak belajar anak tanpa mengorbankan standar."},
{"id":"TKP-3193", "q":"Seorang polisi berbeda suku dengan pelanggar lalu lintas dituduh pilih kasih saat menilang. Sikap polisi yang paling tepat adalah ....", "opts":[{"t":"Menjelaskan pelanggaran secara profesional, menunjukkan bukti, dan mempersilakan menempuh mekanisme keberatan resmi", "s":5},{"t":"Bertindak prosedural dan transparan agar tidak ada prasangka", "s":4},{"t":"Membatalkan tilang karena dituduh", "s":3},{"t":"Menambah denda karena tersinggung", "s":2},{"t":"Menghina suku pelanggar", "s":1}], "ex":"Penegakan hukum yang profesional dan transparan adalah jawaban terbaik atas tuduhan bias suku. Bukti mengalahkan prasangka."},
{"id":"TKP-3194", "q":"Warga adat ingin wilayahnya ditetapkan sebagai desa adat, tetapi persyaratan administratif belum lengkap. Bantuan Anda sebagai pendamping yang paling tepat adalah ....", "opts":[{"t":"Mendampingi pemenuhan persyaratan langkah demi langkah dan mengadvokasikannya ke pemerintah daerah", "s":5},{"t":"Membantu proses administrasi hingga tuntas", "s":4},{"t":"Menyatakan tidak mungkin karena syarat kurang", "s":3},{"t":"Memalsukan dokumen pendukung", "s":2},{"t":"Mengabaikan aspirasi mereka", "s":1}], "ex":"Pengakuan desa adat adalah hak konstitusional yang difasilitasi negara. Pendampingan sabar lebih bermakna daripada penolakan cepat."},
{"id":"TKP-3195", "q":"Dalam arisan RT, anggota berbeda suku selalu mendapat giliran terakhir tanpa alasan jelas. Sebagai ketua RT, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menegakkan sistem giliran yang adil dan transparan, memastikan tidak ada diskriminasi suku", "s":5},{"t":"Memperbaiki sistem arisan agar adil bagi semua", "s":4},{"t":"Membiarkan karena sudah kebiasaan", "s":3},{"t":"Mengeluarkan anggota yang protes", "s":2},{"t":"Membenarkan karena ia pendatang", "s":1}], "ex":"Keadilan dimulai dari hal kecil seperti arisan. Sistem yang transparan menutup celah diskriminasi suku."},
{"id":"TKP-3196", "q":"Seorang guru diminta mengajar di daerah adat terpencil dan khawatir tidak diterima. Saran Anda sebagai atasannya yang paling tepat adalah ....", "opts":[{"t":"Membekalinya pemahaman budaya setempat, mengenalkannya pada tokoh adat, dan mendukung adaptasinya", "s":5},{"t":"Mempersiapkan pembekalan budaya dan pendampingan awal", "s":4},{"t":"Memaksanya berangkat tanpa persiapan", "s":3},{"t":"Membatalkan penugasannya", "s":2},{"t":"Menganggap kekhawatirannya berlebihan", "s":1}], "ex":"Guru yang dibekali pemahaman budaya akan diterima sebagai keluarga. Persiapan yang baik adalah separuh keberhasilan pengabdian."},
{"id":"TKP-3197", "q":"Warga adat memprotes papan nama kantor desa yang hanya berbahasa Indonesia tanpa aksara daerahnya. Tuntutan mereka wajar. Tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Menambahkan aksara/nama daerah pada papan nama sebagai penghargaan identitas budaya setempat", "s":5},{"t":"Mengakomodasi identitas bahasa daerah dalam fasilitas publik", "s":4},{"t":"Menolak karena aturan penyeragaman", "s":3},{"t":"Mengabaikan protes tersebut", "s":2},{"t":"Menurunkan papan nama yang ada", "s":1}], "ex":"Ruang publik yang dwibahasa adalah penghormatan nyata pada identitas lokal. Kebanggaan budaya memperkuat persatuan."},
{"id":"TKP-3198", "q":"Dalam musrenbang, usulan warga adat selalu kalah suara dengan usulan kelompok mayoritas. Sebagai fasilitator, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Memastikan mekanisme musyawarah memberi ruang adil bagi usulan minoritas adat, bukan sekadar voting mayoritas", "s":5},{"t":"Mendorong deliberasi yang inklusif bagi semua kelompok", "s":4},{"t":"Mengikuti hasil voting apa adanya", "s":3},{"t":"Mengabaikan usulan minoritas", "s":2},{"t":"Memihak mayoritas agar acara cepat selesai", "s":1}], "ex":"Musyawarah bukan sekadar hitung suara, melainkan menjamin keadilan bagi yang lemah. Fasilitator menjaga marwah deliberasi."},
{"id":"TKP-3199", "q":"Seorang dokter diminta keluarga pasien adat untuk tidak memberitahu diagnosis buruk langsung kepada pasien sesuai adatnya. Sikap dokter yang paling tepat adalah ....", "opts":[{"t":"Menghormati permintaan keluarga sepanjang pasien dewasa kompeten dilibatkan sesuai etik kedokteran, dengan komunikasi bertahap yang bijak", "s":5},{"t":"Menyesuaikan cara penyampaian diagnosis dengan nilai budaya keluarga", "s":4},{"t":"Menyampaikan blak-blakan tanpa peduli adat", "s":3},{"t":"Menyembunyikan diagnosis sepenuhnya", "s":2},{"t":"Menolak merawat pasien tersebut", "s":1}], "ex":"Etika kedokteran menghormati otonomi pasien dalam bingkai budayanya. Penyampaian bertahap yang bijak menjembatani keduanya."},
{"id":"TKP-3200", "q":"Generasi muda suatu suku lebih bangga budaya asing daripada adatnya sendiri. Sebagai budayawan ASN, langkah Anda yang paling tepat adalah ....", "opts":[{"t":"Mengemas pelestarian adat dalam format modern yang menarik generasi muda tanpa menghilangkan esensinya", "s":5},{"t":"Membuat program budaya yang relevan dengan gaya hidup anak muda", "s":4},{"t":"Mengkritik generasi muda sebagai tidak berbudaya", "s":3},{"t":"Membiarkan arus zaman", "s":2},{"t":"Memaksa mengikuti adat secara kaku", "s":1}], "ex":"Adat lestari bila hidup di hati generasi muda. Kemasan modern bukan pengkhianatan, melainkan strategi pewarisan budaya."},
{"id":"TKP-3201", "q":"Di kantor Anda, pegawai berbeda suku dan keyakinan akan mengadakan syukuran bersama. Panitia bingung menentukan format acara. Saran Anda yang paling tepat adalah ....", "opts":[{"t":"Mengusulkan format syukuran kebersamaan yang netral dan inklusif, dengan doa bergiliran sesuai keyakinan masing-masing", "s":5},{"t":"Menyarankan acara yang menghormati semua latar belakang pegawai", "s":4},{"t":"Menyerahkan sepenuhnya pada panitia mayoritas", "s":3},{"t":"Mengusulkan dibatalkan saja", "s":2},{"t":"Memaksakan format satu keyakinan", "s":1}], "ex":"Syukuran bersama adalah perekat keberagaman kantor. Format inklusif membuat semua pegawai merasa memiliki acara."},
{"id":"TKP-3202", "q":"Ruang ibadah kecil di kantor hanya cukup untuk satu keyakinan, padahal pegawai beragam. Sebagai pengelola, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Mengusulkan penjadwalan bergilir yang adil atau perluasan ruang ibadah bagi semua keyakinan", "s":5},{"t":"Mengatur penggunaan bersama yang disepakati semua pihak", "s":4},{"t":"Membiarkan dipakai satu keyakinan saja", "s":3},{"t":"Menutup ruang ibadah tersebut", "s":2},{"t":"Melarang ibadah di kantor", "s":1}], "ex":"Fasilitas ibadah kantor adalah hak semua pegawai berkeyakinan. Pengaturan bergilir yang adil mencerminkan keadilan institusi."},
{"id":"TKP-3203", "q":"Seorang pegawai mengenakan atribut keyakinan yang mencolok dan ditegur rekan karena dianggap tidak profesional. Sebagai atasan, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menegaskan bahwa atribut keyakinan adalah hak yang dilindungi, sepanjang tidak melanggar aturan pakaian dinas", "s":5},{"t":"Membela haknya berbusana sesuai keyakinan dalam koridor aturan", "s":4},{"t":"Memintanya melepas atribut agar seragam", "s":3},{"t":"Membiarkan rekan terus menegurnya", "s":2},{"t":"Memberinya sanksi disiplin", "s":1}], "ex":"Kebebasan berkeyakinan termasuk ekspresinya dalam berbusana. Aturan dinas ditegakkan tanpa menghapus hak konstitusional."},
{"id":"TKP-3204", "q":"Dalam tim kerja yang majemuk, perbedaan suku memicu pengelompokan (geng) yang mengganggu kekompakan. Sebagai ketua tim, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Merotasi komposisi kelompok kerja secara berkala dan membangun kegiatan kebersamaan lintas latar", "s":5},{"t":"Memecah pengelompokan dengan penugasan campuran", "s":4},{"t":"Membiarkan karena itu alami", "s":3},{"t":"Membubarkan tim", "s":2},{"t":"Memihak kelompok suku mayoritas", "s":1}], "ex":"Kekompakan tim majemuk dibangun dengan desain kerja yang memaksa kolaborasi lintas latar. Keberagaman yang dikelola menjadi kekuatan."},
{"id":"TKP-3205", "q":"Kantin kantor hanya menyediakan menu yang tidak sesuai pantangan keyakinan sebagian pegawai. Sebagai pengelola, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menyediakan variasi menu yang mengakomodasi pantangan keyakinan mayoritas pegawai", "s":5},{"t":"Menambah pilihan menu yang inklusif", "s":4},{"t":"Membiarkan karena urusan vendor", "s":3},{"t":"Menyarankan membawa bekal sendiri", "s":2},{"t":"Menganggap tuntutan mereka berlebihan", "s":1}], "ex":"Kantin kantor melayani semua keyakinan pegawainya. Variasi menu adalah layanan dasar, bukan kemewahan."},
{"id":"TKP-3206", "q":"Pegawai berbeda keyakinan dengan Anda sedang menjalankan ibadah puasa dan terlihat kesulitan fokus. Sebagai rekan satu ruangan, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menawarkan bantuan tugas yang bisa dibantu dan menjaga suasana kondusif tanpa mengungkit puasanya", "s":5},{"t":"Membantu pekerjaannya dengan tulus", "s":4},{"t":"Membiarkannya berjuang sendiri", "s":3},{"t":"Menyuruhnya membatalkan puasa", "s":2},{"t":"Mengejeknya lemah", "s":1}], "ex":"Empati lintas keyakinan diwujudkan dalam tindakan nyata. Bantuan tulus mempererat persaudaraan sekantor."},
{"id":"TKP-3207", "q":"Dalam rekrutmen tenaga honorer, ada bisikan agar memprioritaskan suku tertentu. Sebagai panitia, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menolak bisikan dan menegakkan seleksi berbasis kompetensi yang buta suku", "s":5},{"t":"Mempertahankan objektivitas seleksi", "s":4},{"t":"Mempertimbangkan bisikan tersebut", "s":3},{"t":"Mengikuti bisikan demi keamanan posisi", "s":2},{"t":"Membocorkan soal kepada suku yang dibisikkan", "s":1}], "ex":"Integritas rekrutmen diuji oleh bisikan. Menolak dengan tegas menjaga marwah institusi dan keadilan bagi semua suku."},
{"id":"TKP-3208", "q":"Acara perpisahan pegawai diisi dengan hiburan yang menyinggung keyakinan sebagian hadirin. Sebagai MC, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Segera mengalihkan dengan elegan, meminta maaf atas ketidaknyamanan, dan melanjutkan dengan segmen yang inklusif", "s":5},{"t":"Mengoreksi arah acara secara halus", "s":4},{"t":"Membiarkan berlanjut", "s":3},{"t":"Ikut tertawa agar suasana cair", "s":2},{"t":"Menambah materi yang lebih menyinggung", "s":1}], "ex":"MC adalah penjaga kenyamanan semua hadirin lintas keyakinan. Koreksi cepat dan elegan menyelamatkan acara."},
{"id":"TKP-3209", "q":"Pegawai baru dari suku minoritas merasa dikucilkan dalam pergaulan kantor. Sebagai senior, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Aktif merangkulnya, mengenalkannya pada rekan lain, dan memastikan ia merasa diterima", "s":5},{"t":"Mengajaknya bergabung dalam aktivitas kantor", "s":4},{"t":"Membiarkannya beradaptasi sendiri", "s":3},{"t":"Menasihatinya agar tidak terlalu sensitif", "s":2},{"t":"Ikut mengucilkannya", "s":1}], "ex":"Inklusi di tempat kerja dimulai dari keramahan personal. Merangkul yang minoritas adalah kepemimpinan moral sehari-hari."},
{"id":"TKP-3210", "q":"Jadwal dinas luar bertepatan dengan hari besar keyakinan seorang anggota tim. Ia meminta digantikan. Sebagai ketua tim, keputusan Anda yang paling tepat adalah ....", "opts":[{"t":"Mengatur pergantian secara adil dan mencatatnya agar beban terbagi rata", "s":5},{"t":"Mencarikan pengganti dengan sistem yang transparan", "s":4},{"t":"Menolak karena tugas sudah dibagi", "s":3},{"t":"Memaksanya tetap berangkat", "s":2},{"t":"Menggantinya tetapi memotong haknya", "s":1}], "ex":"Hari besar keyakinan adalah hak yang dihormati tim. Sistem pergantian yang adil menjaga kekompakan tanpa korban."},
{"id":"TKP-3211", "q":"Di papan pengumuman kantor, seseorang menempelkan ujaran yang menyindir keyakinan tertentu. Sebagai petugas, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Melepas ujaran tersebut, mencari pelakunya untuk dibina, dan mengingatkan tentang etika kerukunan", "s":5},{"t":"Menurunkan tempelan dan memberikan pembinaan", "s":4},{"t":"Membiarkan karena kebebasan berpendapat", "s":3},{"t":"Ikut menyebarkannya", "s":2},{"t":"Membalas dengan ujaran balasan", "s":1}], "ex":"Ruang publik kantor harus steril dari ujaran kebencian keyakinan. Tindakan tegas yang edukatif mencegah pengulangan."},
{"id":"TKP-3212", "q":"Pegawai berbeda suku dengan Anda dipromosikan dan sebagian rekan menduga karena kedekatan suku dengan pimpinan. Sebagai rekan, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menilai berdasarkan rekam kinerjanya yang objektif dan tidak ikut menyebarkan prasangka", "s":5},{"t":"Menghindari gosip dan melihat prestasinya", "s":4},{"t":"Ikut menyebarkan dugaan tersebut", "s":3},{"t":"Memprotes promosinya", "s":2},{"t":"Memusuhinya", "s":1}], "ex":"Prasangka suku meracuni profesionalitas. Menilai berbasis kinerja adalah kedewasaan berorganisasi."},
{"id":"TKP-3213", "q":"Kantor mengadakan lomba 17 Agustus dengan kategori busana daerah. Peserta dari suku minoritas minder. Sebagai panitia, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menyemangatinya bahwa setiap busana daerah punya keunikan dan memastikan penilaian yang adil", "s":5},{"t":"Memberi dukungan agar percaya diri tampil", "s":4},{"t":"Membiarkannya mundur", "s":3},{"t":"Menyarankan memakai busana suku mayoritas", "s":2},{"t":"Menertawakan busananya", "s":1}], "ex":"Setiap busana daerah adalah kebanggaan Indonesia. Dukungan panitia menumbuhkan keberanian tampil bagi yang minoritas."},
{"id":"TKP-3214", "q":"Rapat dinas molor hingga melewati waktu ibadah magrib para peserta. Sebagai pimpinan rapat, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menghentikan sejenak untuk ibadah lalu melanjutkan, atau menutup rapat dan melanjutkan esok hari", "s":5},{"t":"Memberi jeda ibadah yang layak", "s":4},{"t":"Melanjutkan sampai selesai", "s":3},{"t":"Menyalahkan peserta yang gelisah", "s":2},{"t":"Melarang meninggalkan ruangan", "s":1}], "ex":"Rapat yang baik menghormati kewajiban ibadah pesertanya. Jeda sejenak tidak meruntuhkan produktivitas."},
{"id":"TKP-3215", "q":"Seorang pegawai bercanda membawa-bawa suku dan keyakinan rekan hingga tersinggung. Sebagai atasan yang mendengar, tindakan Anda yang paling tepat adalah ....", "opts":[{"t":"Menegur secara privat, menjelaskan batas candaan, dan meminta permintaan maaf yang tulus", "s":5},{"t":"Memberikan pembinaan tentang etika pergaulan", "s":4},{"t":"Menganggapnya candaan biasa", "s":3},{"t":"Menertawakan bersama", "s":2},{"t":"Menghukum berat tanpa pembinaan", "s":1}], "ex":"Candaan SARA bukan humor melainkan pelecehan. Teguran privat yang mendidik lebih efektif daripada hukuman memalukan."},
{"id":"TKP-3216", "q":"Tim Anda ditugaskan di daerah dengan mayoritas keyakinan berbeda. Seorang anggota menolak berangkat. Sebagai ketua tim, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Memberikan pembekalan wawasan keberagaman, meyakinkannya tentang profesionalitas tugas, dan mendampingi adaptasinya", "s":5},{"t":"Membina pemahamannya tentang tugas lintas keyakinan", "s":4},{"t":"Menggantinya dengan orang lain", "s":3},{"t":"Memaksanya berangkat dengan ancaman", "s":2},{"t":"Membiarkannya mangkir", "s":1}], "ex":"Penolakan berbasis keyakinan diatasi dengan pembekalan, bukan paksaan. ASN profesional melayani di mana pun ditugaskan."},
{"id":"TKP-3217", "q":"Dalam evaluasi kinerja, bawahan berbeda keyakinan dengan Anda mendapat nilai rendah dan menduga dinilai tidak objektif. Sebagai penilai, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Membuka hasil penilaian berbasis indikator terukur, menjelaskan kekurangannya secara objektif, dan memberi rencana perbaikan", "s":5},{"t":"Menunjukkan bukti kinerja yang transparan", "s":4},{"t":"Mempertahankan nilai tanpa penjelasan", "s":3},{"t":"Menaikkan nilainya agar tidak dituduh", "s":2},{"t":"Menurunkan lebih jauh karena berani protes", "s":1}], "ex":"Penilaian kinerja yang transparan dan berbasis data adalah tameng terbaik dari tuduhan bias keyakinan."},
{"id":"TKP-3218", "q":"Kantor Anda menerima magang dari berbagai suku dan keyakinan. Program orientasi perlu disiapkan. Yang paling tepat Anda usulkan adalah ....", "opts":[{"t":"Orientasi yang memperkenalkan keberagaman kantor sebagai kekuatan dan menanamkan nilai toleransi sejak hari pertama", "s":5},{"t":"Menyisipkan materi keberagaman dalam orientasi", "s":4},{"t":"Orientasi standar tanpa materi khusus", "s":3},{"t":"Mengelompokkan magang berdasarkan kesamaan latar", "s":2},{"t":"Tidak perlu orientasi", "s":1}], "ex":"Orientasi adalah fondasi budaya kerja inklusif. Menanamkan toleransi sejak awal mencegah gesekan di kemudian hari."},
{"id":"TKP-3219", "q":"Pegawai senior selalu menyindir keyakinan juniornya dengan dalih menasihati. Junior tersebut tertekan. Sebagai rekan, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menegur senior secara bijak dan mendukung junior agar berani bersuara melalui jalur yang tepat", "s":5},{"t":"Membela junior dan mengingatkan senior tentang batas", "s":4},{"t":"Menasihati junior agar bersabar menghadapi senior", "s":3},{"t":"Diam karena tidak ingin bermusuhan dengan senior", "s":2},{"t":"Ikut menasihati dengan cara yang sama", "s":1}], "ex":"Menasihati bukan lisensi merendahkan keyakinan. Keberanian menegur yang senior demi yang lemah adalah integritas."},
{"id":"TKP-3220", "q":"Dalam perjalanan dinas, rombongan berbeda keyakinan kesulitan mencari tempat ibadah di daerah tujuan. Sebagai koordinator, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Proaktif mencari informasi tempat ibadah tiap keyakinan sebelum berangkat dan menyusun jadwal yang akomodatif", "s":5},{"t":"Mempersiapkan fasilitas ibadah dalam perencanaan perjalanan", "s":4},{"t":"Membiarkan masing-masing mencari sendiri", "s":3},{"t":"Meminta mereka menunda ibadah sampai pulang", "s":2},{"t":"Menganggap itu bukan tanggung jawab koordinator", "s":1}], "ex":"Koordinator yang baik mengantisipasi kebutuhan ibadah seluruh rombongan. Perencanaan inklusif adalah standar profesionalitas."},
{"id":"TKP-3221", "q":"Seorang pegawai mengajukan pindah divisi karena merasa didiskriminasi keyakinannya oleh atasannya. Sebagai HRD, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menindaklanjuti dengan investigasi objektif, melindungi pelapor, dan menindak terbukti ada diskriminasi", "s":5},{"t":"Memeriksa kebenaran laporannya secara serius", "s":4},{"t":"Langsung memindahkan tanpa investigasi", "s":3},{"t":"Mengabaikan laporannya", "s":2},{"t":"Menyalahkan pegawai yang melapor", "s":1}], "ex":"Laporan diskriminasi keyakinan wajib ditindaklanjuti serius. Investigasi objektif melindungi korban sekaligus keadilan bagi terlapor."},
{"id":"TKP-3222", "q":"Kantor akan memasang dekorasi hari besar keagamaan. Sebagian pegawai usul hanya agamanya yang ditampilkan. Keputusan Anda sebagai pimpinan yang paling tepat adalah ....", "opts":[{"t":"Menampilkan dekorasi yang merayakan keberagaman atau memberi ruang bergiliran bagi tiap keyakinan", "s":5},{"t":"Mengatur representasi yang adil bagi semua", "s":4},{"t":"Mengikuti usulan mayoritas", "s":3},{"t":"Melarang semua dekorasi keagamaan", "s":2},{"t":"Membiarkan perdebatan berkepanjangan", "s":1}], "ex":"Ruang kerja milik semua keyakinan. Representasi yang adil atau netralitas total, bukan dominasi mayoritas."},
{"id":"TKP-3223", "q":"Bawahan Anda berbeda suku dan sering tidak diajak dalam obrolan santai tim. Ia merasa tersisih. Sebagai atasan, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menciptakan momen kebersamaan yang inklusif dan menegur halus budaya eksklusif dalam tim", "s":5},{"t":"Mendorong tim merangkulnya dalam interaksi sehari-hari", "s":4},{"t":"Menasihatinya agar lebih proaktif bergaul", "s":3},{"t":"Menganggapnya masalah pribadi", "s":2},{"t":"Menyalahkannya karena tidak bisa membaur", "s":1}], "ex":"Eksklusi sosial berbasis suku merusak psikologis pegawai. Pemimpin bertanggung jawab atas iklim inklusif timnya."},
{"id":"TKP-3224", "q":"Dalam pembagian tugas piket hari besar, pegawai minoritas keyakinan selalu mendapat jadwal yang merugikan. Sebagai penyusun jadwal, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menyusun jadwal berbasis sistem rotasi yang adil dan transparan bagi semua", "s":5},{"t":"Memperbaiki sistem penjadwalan agar berkeadilan", "s":4},{"t":"Membiarkan pola yang ada", "s":3},{"t":"Memberinya kompensasi tanpa memperbaiki sistem", "s":2},{"t":"Menyalahkannya karena minoritas", "s":1}], "ex":"Keadilan sistemik mengalahkan kebaikan insidental. Rotasi transparan menghapus pola diskriminasi terselubung."},
{"id":"TKP-3225", "q":"Seorang pegawai memakai bahasa daerahnya saat rapat resmi sehingga sebagian peserta tidak paham. Ia berdalih itu identitas sukunya. Sebagai pimpinan rapat, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menegaskan penggunaan bahasa Indonesia dalam forum resmi sambil menghormati bahasa daerah di ruang informal", "s":5},{"t":"Mengingatkan tata tertib berbahasa dengan bijak", "s":4},{"t":"Membiarkannya demi menghormati identitas", "s":3},{"t":"Melarang total penggunaan bahasa daerah di kantor", "s":2},{"t":"Menegurnya dengan kasar di depan peserta", "s":1}], "ex":"Bahasa Indonesia adalah bahasa persatuan dalam forum resmi. Penghormatan pada bahasa daerah diwujudkan di ruang yang tepat."},
{"id":"TKP-3226", "q":"Beredar meme yang mengejek ritual ibadah suatu agama di grup pertemanan Anda. Sebagian tertawa. Sebagai ASN, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menegur pembuatnya dengan bijak, menjelaskan bahwa mengejek ibadah adalah pelanggaran toleransi, dan tidak ikut menyebarkan", "s":5},{"t":"Mengingatkan grup tentang batas humor yang menghormati keyakinan", "s":4},{"t":"Diam dan keluar dari grup", "s":3},{"t":"Tertawa agar tidak dikucilkan", "s":2},{"t":"Ikut membuat meme balasan yang lebih menyakitkan", "s":1}], "ex":"Ibadah adalah wilayah sakral yang tidak boleh dijadikan bahan olok-olok. ASN menjadi teladan dalam menjaga kehormatan keyakinan."},
{"id":"TKP-3227", "q":"Seorang tokoh masyarakat menyebarkan ceramah yang menyudutkan keyakinan lain. Warga terbelah. Sebagai aparat, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Berkonsultasi dengan tokoh lintas agama dan aparat penegak hukum, mengedepankan pembinaan dan penegakan aturan", "s":5},{"t":"Mengambil langkah pembinaan sesuai koridor hukum yang berlaku", "s":4},{"t":"Membiarkan karena kebebasan berceramah", "s":3},{"t":"Ikut menyebarkan ceramahnya", "s":2},{"t":"Mengusir tokoh tersebut dari desa", "s":1}], "ex":"Kebebasan berdakwah berhenti di ambang kehormatan keyakinan lain. Pembinaan dan penegakan hukum berjalan beriringan menjaga kerukunan."},
{"id":"TKP-3228", "q":"Anak Anda meniru ujaran stereotip suku yang didengarnya dari tontonan. Sikap Anda sebagai orang tua yang paling tepat adalah ....", "opts":[{"t":"Meluruskan dengan sabar, menjelaskan bahwa stereotip itu tidak benar, dan menanamkan penghargaan pada setiap suku", "s":5},{"t":"Mengoreksi dan memberi pemahaman keberagaman", "s":4},{"t":"Membiarkan karena anak-anak", "s":3},{"t":"Menertawakan karena lucu", "s":2},{"t":"Menambah-nambahi stereotipnya", "s":1}], "ex":"Stereotip suku diputus di rumah. Orang tua yang meluruskan sejak dini menanamkan toleransi seumur hidup."},
{"id":"TKP-3229", "q":"Dalam kampanye pilkada, beredar isu SARA yang menyudutkan keyakinan salah satu calon. Sebagai ASN yang netral, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Tidak ikut menyebarkan, mengingatkan lingkungan tentang netralitas ASN, dan melaporkan konten provokatif melalui jalur resmi", "s":5},{"t":"Menjaga netralitas dan tidak terlibat politik SARA", "s":4},{"t":"Diam saja", "s":3},{"t":"Ikut menyebarkan karena menarik", "s":2},{"t":"Terlibat dalam tim yang menyebar isu", "s":1}], "ex":"Netralitas ASN adalah benteng demokrasi dari politik SARA. Melaporkan provokasi adalah kewajiban, bukan pilihan."},
{"id":"TKP-3230", "q":"Seorang guru menemukan coretan bernada SARA yang merendahkan salah satu keyakinan di meja kelas. Yang paling tepat ia lakukan adalah ....", "opts":[{"t":"Menghapus coretan, menjadikannya momen pembinaan toleransi bagi seluruh kelas tanpa menghakimi", "s":5},{"t":"Membersihkan dan memberikan nasihat keberagaman", "s":4},{"t":"Membiarkan petugas kebersihan menghapus", "s":3},{"t":"Mengabaikan", "s":2},{"t":"Mencari pelaku untuk dihukum berat", "s":1}], "ex":"Coretan SARA di sekolah adalah alarm dini lunturnya toleransi. Pembinaan kolektif lebih mendidik daripada perburuan pelaku."},
{"id":"TKP-3231", "q":"Warga berbeda keyakinan dengan Anda menjadi korban bencana dan membutuhkan bantuan segera. Relawan dari keyakinan Anda ragu membantu. Sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menggerakkan bantuan tanpa memandang keyakinan karena kemanusiaan melampaui sekat agama", "s":5},{"t":"Memastikan bantuan disalurkan kepada semua korban", "s":4},{"t":"Mendahulukan korban sekeyakinan", "s":3},{"t":"Menolak membantu korban beda keyakinan", "s":2},{"t":"Memanfaatkan bencana untuk menyebarkan keyakinan", "s":1}], "ex":"Bencana tidak memilih keyakinan korbannya, maka bantuan pun tidak boleh memilih. Kemanusiaan adalah agama universal relawan."},
{"id":"TKP-3232", "q":"Di media komunitas, seseorang menulis bahwa keyakinan tertentu tidak pantas ada di Indonesia. Sebagai moderator yang juga ASN, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menghapus ujaran kebencian, memberi peringatan edukatif, dan menegaskan aturan komunitas yang menghormati semua keyakinan", "s":5},{"t":"Menindak tegas sesuai aturan dengan pendekatan pembinaan", "s":4},{"t":"Membiarkan sebagai kebebasan pendapat", "s":3},{"t":"Ikut menyetujui tulisannya", "s":2},{"t":"Memblokir semua diskusi agama", "s":1}], "ex":"Kebebasan berpendapat tidak mencakup ujaran kebencian terhadap keyakinan. Moderasi yang tegas melindungi ruang percakapan yang sehat."},
{"id":"TKP-3233", "q":"Seorang siswa menolak duduk sebangku dengan siswa berbeda keyakinan karena ajaran orang tuanya. Sebagai guru, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Berkomunikasi dengan orang tua dan siswa, menanamkan nilai toleransi secara bertahap dengan pendekatan yang santun", "s":5},{"t":"Membina pemahaman keberagaman bagi siswa dan orang tuanya", "s":4},{"t":"Memaksanya duduk sebangku", "s":3},{"t":"Membiarkan penolakan tersebut", "s":2},{"t":"Menghukum siswa karena dianggap tidak toleran", "s":1}], "ex":"Prasangka yang diwariskan orang tua diluruskan sekolah dengan pembinaan bertahap. Paksaan justru memperkuat penolakan."},
{"id":"TKP-3234", "q":"Tetangga Anda memasang simbol keyakinannya besar-besar hingga menutupi pandangan jalan. Warga lain protes. Sebagai ketua RT, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Berdialog dengan tetangga untuk penyesuaian ukuran/penempatan yang menghormati keyakinannya tanpa mengganggu kepentingan umum", "s":5},{"t":"Memediasi penataan yang disepakati bersama", "s":4},{"t":"Memerintahkan pencopotan total", "s":3},{"t":"Membiarkan karena hak berkeyakinan", "s":2},{"t":"Menghasut warga mencopot paksa", "s":1}], "ex":"Ekspresi keyakinan di ruang publik dibatasi kepentingan umum. Dialog menghasilkan penyesuaian yang bermartabat bagi semua."},
{"id":"TKP-3235", "q":"Dalam diskusi keluarga, perbedaan tafsir keyakinan memicu pertengkaran. Sebagai anggota keluarga yang dituakan, sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menengahi dengan bijak, menegaskan bahwa perbedaan tafsir adalah rahmat, dan mengajak kembali pada nilai kasih", "s":5},{"t":"Mendamaikan dengan menekankan persaudaraan di atas perbedaan tafsir", "s":4},{"t":"Memihak tafsir yang Anda anut", "s":3},{"t":"Membiarkan bertengkar", "s":2},{"t":"Mengusir yang berbeda tafsir", "s":1}], "ex":"Perbedaan tafsir dalam satu keyakinan pun menuntut kedewasaan. Yang dituakan menjadi jangkar kasih di tengah perbedaan."},
{"id":"TKP-3236", "q":"Seorang pedagang menolak melayani pembeli beda keyakinan dengan alasan menjaga kesucian dagangannya. Sebagai petugas pasar, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Membina pedagang bahwa pasar adalah ruang publik untuk semua keyakinan, dengan sanksi bertahap bila menolak berubah", "s":5},{"t":"Menegakkan aturan nondiskriminasi di area pasar", "s":4},{"t":"Membiarkan karena hak pedagang", "s":3},{"t":"Mendukung penolakannya", "s":2},{"t":"Mengusir pembeli yang ditolak", "s":1}], "ex":"Ruang ekonomi publik tidak boleh disekat keyakinan. Pembinaan bertahap lebih manusiawi daripada hukuman seketika."},
{"id":"TKP-3237", "q":"Anak muda di kampung Anda terpengaruh paham keagamaan yang kaku dan memusuhi tradisi lokal. Sebagai tokoh pemuda, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Mengajak dialog, memperkenalkan Islam/Kristen/Hindu/Buddha yang moderat dan ramah budaya melalui kegiatan positif", "s":5},{"t":"Membina dengan pendekatan keagamaan yang sejuk", "s":4},{"t":"Membiarkan karena itu pilihannya", "s":3},{"t":"Mengucilkannya dari pergaulan", "s":2},{"t":"Melawannya dengan kekerasan", "s":1}], "ex":"Moderasi beragama adalah vaksin terbaik bagi kekakuan. Dialog dan keteladanan lebih ampuh daripada pengucilan."},
{"id":"TKP-3238", "q":"Warga meminta Anda memilihkan sekolah berdasarkan keyakinan mayoritasnya agar anaknya tidak terpengaruh. Sebagai konselor pendidikan, saran Anda yang paling tepat adalah ....", "opts":[{"t":"Menyarankan memilih berdasarkan kualitas pendidikan dengan tetap memperhatikan pembinaan keyakinan di rumah", "s":5},{"t":"Mengarahkan pada mutu sekolah sebagai kriteria utama", "s":4},{"t":"Menyarankan sekolah sekeyakinan saja", "s":3},{"t":"Menolak memberi saran", "s":2},{"t":"Menakut-nakuti tentang sekolah majemuk", "s":1}], "ex":"Kualitas pendidikan adalah kriteria utama memilih sekolah. Keyakinan anak justru kokoh bila dibina di rumah yang hangat."},
{"id":"TKP-3239", "q":"Seorang calon kepala desa berkampanye dengan mengklaim keyakinannya paling benar. Sebagai panitia pilkades, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menegakkan aturan kampanye yang melarang eksploitasi SARA dan memberi peringatan resmi", "s":5},{"t":"Menindak pelanggaran kampanye berbasis keyakinan", "s":4},{"t":"Membiarkan sebagai strategi kampanye", "s":3},{"t":"Mendukung calon tersebut", "s":2},{"t":"Mendiskualifikasi tanpa prosedur", "s":1}], "ex":"Kontestasi demokrasi tidak boleh menunggangi keyakinan. Penegakan aturan kampanye melindungi kerukunan warga."},
{"id":"TKP-3240", "q":"Di tempat kerja, ada yang menyebarkan kabar bahwa keyakinan tertentu melarang loyalitas pada negara. Sebagai ASN, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Meluruskan dengan fakta bahwa seluruh keyakinan yang diakui negara sejalan dengan nasionalisme, dan melaporkan penyebar kabar", "s":5},{"t":"Meluruskan kabar bohong dengan penjelasan yang benar", "s":4},{"t":"Diam karena takut diserang", "s":3},{"t":"Ikut mempercayai kabar tersebut", "s":2},{"t":"Ikut menyebarkannya", "s":1}], "ex":"Fitnah terhadap keyakinan merusak persatuan. ASN wajib menjadi penangkal kabar bohong dengan fakta."},
{"id":"TKP-3241", "q":"Siswa menulis esai yang merendahkan keyakinan temannya sebagai tugas. Sebagai guru, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Mengembalikan esai dengan catatan pembinaan, meminta revisi yang menghormati, dan menjadikannya pelajaran toleransi", "s":5},{"t":"Membina melalui revisi tugas yang edukatif", "s":4},{"t":"Memberi nilai jelek tanpa penjelasan", "s":3},{"t":"Memuji keberaniannya berpendapat", "s":2},{"t":"Membacakan esainya di depan kelas", "s":1}], "ex":"Tugas sekolah bukan panggung merendahkan keyakinan. Revisi yang dibina mengubah kesalahan menjadi pembelajaran."},
{"id":"TKP-3242", "q":"Warga beda keyakinan ingin menjadi pengurus karang taruna tetapi ditolak karena dianggap tidak cocok. Sebagai pembina, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menegaskan keterbukaan organisasi kepemudaan bagi semua keyakinan dan memfasilitasi pemilihannya secara demokratis", "s":5},{"t":"Membuka ruang kepemimpinan yang inklusif", "s":4},{"t":"Menyarankan membentuk karang taruna sendiri", "s":3},{"t":"Mendukung penolakan tersebut", "s":2},{"t":"Membubarkan karang taruna", "s":1}], "ex":"Organisasi kepemudaan adalah kawah candradimuka kebangsaan. Keterbukaan keyakinan melahirkan pemimpin masa depan yang toleran."},
{"id":"TKP-3243", "q":"Seorang narapidana berbeda keyakinan dengan petugas ingin menjalankan ibadah puasa sunah. Petugas ragu mengizinkan. Sikap yang paling tepat adalah ....", "opts":[{"t":"Mengizinkan sesuai aturan lapas karena pembinaan spiritual adalah hak warga binaan semua keyakinan", "s":5},{"t":"Memfasilitasi ibadahnya dalam koridor aturan", "s":4},{"t":"Menolak karena merepotkan", "s":3},{"t":"Mengizinkan tetapi mengurangi jatah makannya", "s":2},{"t":"Mengejek keyakinannya", "s":1}], "ex":"Pembinaan spiritual warga binaan tidak mengenal sekat keyakinan. Ibadah yang difasilitasi mempercepat rehabilitasi."},
{"id":"TKP-3244", "q":"Dalam acara donor darah, panitia menolak pendonor beda keyakinan dengan alasan tidak jelas. Sebagai koordinator, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menegaskan donor darah terbuka untuk semua keyakinan karena darah tidak mengenal agama", "s":5},{"t":"Membuka pendaftaran tanpa diskriminasi", "s":4},{"t":"Membiarkan penolakan tersebut", "s":3},{"t":"Mendukung penolakan", "s":2},{"t":"Membatalkan acara", "s":1}], "ex":"Setetes darah menyelamatkan tanpa menanya keyakinan. Kemanusiaan donor darah adalah teladan toleransi tertinggi."},
{"id":"TKP-3245", "q":"Tetangga Anda mengadakan selamatan dengan mengundang semua warga lintas keyakinan. Sebagian menolak hadir. Sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Hadir dengan gembira sebagai wujud persaudaraan, menghormati tuan rumah", "s":5},{"t":"Menghadiri undangan sebagai tetangga yang baik", "s":4},{"t":"Tidak hadir tanpa alasan", "s":3},{"t":"Menghadiri tetapi mencela makanannya", "s":2},{"t":"Memprovokasi yang lain untuk tidak hadir", "s":1}], "ex":"Selamatan lintas keyakinan adalah tradisi luhur kerukunan. Kehadiran adalah penghargaan pada persaudaraan bertetangga."},
{"id":"TKP-3246", "q":"Seorang dosen memberikan contoh yang menyudutkan keyakinan tertentu dalam kuliah. Mahasiswa keberatan. Sebagai ketua jurusan, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Membina dosen tentang etika akademik yang netral keyakinan dan memastikan ruang kelas inklusif", "s":5},{"t":"Menegur dan memberikan pembinaan profesional", "s":4},{"t":"Membiarkan karena kebebasan akademik", "s":3},{"t":"Mendukung dosen tersebut", "s":2},{"t":"Memecatnya seketika", "s":1}], "ex":"Kebebasan akademik tidak membenarkan penyudutan keyakinan. Pembinaan menjaga marwah kampus sebagai rumah semua keyakinan."},
{"id":"TKP-3247", "q":"Warga meminta pembangunan gapura dengan ornamen keyakinan tertentu di pintu masuk kampung majemuk. Sebagian warga keberatan. Sebagai ketua RW, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Mengusulkan desain gapura yang netral atau mewakili keberagaman, diputuskan melalui musyawarah", "s":5},{"t":"Memfasilitasi kesepakatan desain yang inklusif", "s":4},{"t":"Menyetujui ornamen satu keyakinan", "s":3},{"t":"Menolak pembangunan gapura", "s":2},{"t":"Membiarkan warga bertikai", "s":1}], "ex":"Simbol ruang publik di kampung majemuk harus merangkul semua. Musyawarah desain mencegah gapura menjadi sumber perpecahan."},
{"id":"TKP-3248", "q":"Anak Anda diejek karena keyakinannya minoritas di sekolah. Ia ingin pindah keyakinan agar diterima. Sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menguatkannya untuk bangga pada keyakinannya, berkoordinasi dengan sekolah menangani perundungan", "s":5},{"t":"Membangun kepercayaan dirinya dan melapor ke sekolah", "s":4},{"t":"Membiarkannya pindah keyakinan", "s":3},{"t":"Menyuruhnya menyembunyikan keyakinannya", "s":2},{"t":"Memarahinya karena lemah", "s":1}], "ex":"Keyakinan bukan pakaian yang diganti demi diterima. Orang tua menguatkan, sekolah menindak perundungan."},
{"id":"TKP-3249", "q":"Dalam seleksi paskibraka, peserta berbeda keyakinan dengan pelatih meraih nilai tertinggi. Ada desakan menggantinya. Sebagai panitia, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Mempertahankan hasil berbasis nilai karena pengabdian pada negara buta keyakinan", "s":5},{"t":"Menegakkan meritokrasi seleksi", "s":4},{"t":"Menggantinya demi meredam desakan", "s":3},{"t":"Mengulang seleksi dengan kriteria tambahan", "s":2},{"t":"Membocorkan keyakinannya ke publik", "s":1}], "ex":"Mengibarkan merah putih adalah hak setiap keyakinan. Meritokrasi melindungi yang berprestasi dari prasangka."},
{"id":"TKP-3250", "q":"Seorang pengusaha beda keyakinan dengan Anda menawarkan kerja sama usaha yang menguntungkan. Sebagian keluarga melarang. Sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menilai tawaran secara profesional dan menerima bila saling menguntungkan, tanpa mencampuradukkan keyakinan", "s":5},{"t":"Mempertimbangkan murni dari sisi bisnis", "s":4},{"t":"Menolak demi menjaga perasaan keluarga", "s":3},{"t":"Menerima tetapi dengan prasangka", "s":2},{"t":"Menuduhnya punya motif menyebarkan keyakinan", "s":1}], "ex":"Bisnis yang sehat dinilai dari profesionalitas, bukan keyakinan mitra. Prasangka hanya menutup rezeki."},
{"id":"TKP-3251", "q":"Terjadi perselisihan batas tanah antara warga dua suku berbeda di desa Anda. Keduanya mengklaim berdasarkan adat masing-masing. Sebagai mediator, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Memfasilitasi musyawarah dengan data pertanahan resmi, menghormati kedua adat, dan mencari titik temu yang adil", "s":5},{"t":"Menengahi berbasis data dan musyawarah yang berimbang", "s":4},{"t":"Memihak warga yang adatnya Anda kenal", "s":3},{"t":"Menyerahkan ke pengadilan tanpa mediasi", "s":2},{"t":"Membiarkan mereka berkelahi", "s":1}], "ex":"Sengketa lintas adat diselesaikan dengan data objektif dan penghormatan dua budaya. Mediator yang adil tidak memihak suku."},
{"id":"TKP-3252", "q":"Dua kelompok pemuda beda keyakinan tawuran dipicu kesalahpahaman antar keduanya. Sebagai tokoh pemuda, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Mendamaikan kedua kelompok, mengajak dialog, dan membangun kegiatan bersama lintas keyakinan", "s":5},{"t":"Memediasi perdamaian dan mencegah provokasi lanjutan", "s":4},{"t":"Membela kelompok yang sekeyakinan dengan Anda", "s":3},{"t":"Membiarkan aparat menangani", "s":2},{"t":"Memprovokasi tawuran susulan", "s":1}], "ex":"Tawuran pemuda beda keyakinan diredam dengan perdamaian aktif. Kegiatan bersama membangun jembatan yang lebih kuat dari prasangka."},
{"id":"TKP-3253", "q":"Warga dua suku berebut sumber mata air untuk sawah masing-masing. Sebagai perangkat desa, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Mengatur pembagian air yang adil berbasis musyawarah dan data kebutuhan, disepakati kedua belah pihak", "s":5},{"t":"Memfasilitasi kesepakatan pembagian yang berkeadilan", "s":4},{"t":"Memberikan ke suku yang lebih dulu mengklaim", "s":3},{"t":"Menutup sumber air untuk semua", "s":2},{"t":"Membiarkan siapa kuat dia dapat", "s":1}], "ex":"Sumber daya alam milik bersama lintas suku. Pembagian adil hasil musyawarah mencegah konflik agraria berkepanjangan."},
{"id":"TKP-3254", "q":"Pedagang asli dan pendatang beda suku bersaing hingga terjadi intimidasi di pasar. Sebagai pengelola pasar, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menegakkan aturan pasar yang adil bagi semua suku, menindak intimidasi, dan memfasilitasi persaingan sehat", "s":5},{"t":"Menertibkan dengan aturan yang setara", "s":4},{"t":"Membela pedagang asli", "s":3},{"t":"Mengusir pedagang pendatang", "s":2},{"t":"Membiarkan intimidasi", "s":1}], "ex":"Pasar adalah ruang ekonomi terbuka semua suku. Intimidasi berbasis kesukuan adalah pelanggaran yang harus ditindak tegas."},
{"id":"TKP-3255", "q":"Dua desa beda suku bersengketa tapal batas hingga nyaris bentrok. Sebagai camat, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Membentuk tim mediasi, merujuk data resmi pertanahan, dan memfasilitasi kesepakatan damai kedua desa", "s":5},{"t":"Menengahi dengan data dan musyawarah", "s":4},{"t":"Memihak desa yang sukunya sama dengan Anda", "s":3},{"t":"Menyerahkan ke polisi tanpa mediasi", "s":2},{"t":"Membiarkan bentrok terjadi", "s":1}], "ex":"Sengketa tapal batas diselesaikan dengan data resmi dan musyawarah. Netralitas camat adalah kunci perdamaian antarwarga."},
{"id":"TKP-3256", "q":"Kelompok warga menolak tetangga beda keyakinan menjadi panitia hari kemerdekaan. Sebagai ketua RT, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menegaskan kepanitiaan terbuka bagi semua warga dan memfasilitasi pembagian tugas yang inklusif", "s":5},{"t":"Membuka kesempatan yang sama bagi seluruh warga", "s":4},{"t":"Mengikuti kehendak kelompok yang menolak", "s":3},{"t":"Membatalkan perayaan", "s":2},{"t":"Mengeluarkan warga yang ditolak dari RT", "s":1}], "ex":"Perayaan kemerdekaan adalah milik semua keyakinan. Kepanitiaan inklusif mencerminkan makna merdeka yang sesungguhnya."},
{"id":"TKP-3257", "q":"Warga suku A menuduh suku B mencuri hasil kebun tanpa bukti. Ketegangan meningkat. Sebagai tokoh masyarakat, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menenangkan kedua pihak, menegaskan perlunya bukti, dan memfasilitasi penyelesaian secara adat dan hukum", "s":5},{"t":"Meredam emosi dan mengarahkan pada pembuktian", "s":4},{"t":"Membenarkan tuduhan suku A", "s":3},{"t":"Mengusir suku B dari kampung", "s":2},{"t":"Memprovokasi perkelahian", "s":1}], "ex":"Tuduhan tanpa bukti antar suku adalah api konflik. Praduga tak bersalah berlaku bagi semua suku tanpa kecuali."},
{"id":"TKP-3258", "q":"Dua ormas kepemudaan beda latar keyakinan berebut pengaruh di kampung. Sebagai lurah, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Merangkul keduanya dalam program kepemudaan bersama yang positif dan mengarahkan kompetisi ke prestasi", "s":5},{"t":"Memfasilitasi kolaborasi kegiatan yang bermanfaat", "s":4},{"t":"Melarang kedua ormas", "s":3},{"t":"Memihak salah satu", "s":2},{"t":"Membiarkan persaingan liar", "s":1}], "ex":"Energi pemuda disalurkan ke kompetisi prestasi, bukan perebutan pengaruh. Kolaborasi lintas keyakinan membangun kampung."},
{"id":"TKP-3259", "q":"Warga pendatang beda suku ingin membuka usaha kuliner khasnya, tetapi warga asli memboikot. Sebagai perangkat desa, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menjamin hak berusaha setiap warga, mengedukasi tentang persaingan sehat, dan mempromosikan keberagaman kuliner", "s":5},{"t":"Melindungi hak usaha dan mendorong persaingan sehat", "s":4},{"t":"Menyarankan pindah usaha ke desa lain", "s":3},{"t":"Mendukung boikot warga asli", "s":2},{"t":"Menutup paksa usahanya", "s":1}], "ex":"Hak berusaha dilindungi tanpa sekat suku. Boikot berbasis kesukuan adalah diskriminasi ekonomi yang harus dilawan."},
{"id":"TKP-3260", "q":"Sengketa warisan melibatkan keluarga beda keyakinan dengan tafsir hukum waris berbeda. Sebagai penasihat, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Merujuk pada hukum positif yang berlaku dan memfasilitasi musyawarah keluarga yang menghormati semua pihak", "s":5},{"t":"Mengarahkan pada penyelesaian hukum yang adil", "s":4},{"t":"Memihak tafsir keyakinan mayoritas keluarga", "s":3},{"t":"Menyerahkan ke pengadilan tanpa musyawarah", "s":2},{"t":"Mengambil bagian warisan sebagai imbalan", "s":1}], "ex":"Hukum waris positif adalah rujukan bersama lintas keyakinan. Musyawarah keluarga menjaga silaturahmi di atas harta."},
{"id":"TKP-3261", "q":"Dua kelompok suporter beda daerah (bernuansa kesukuan) bentrok usai pertandingan. Sebagai aparat keamanan, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Mengamankan dengan tegas dan netral, memisahkan kelompok, dan memproses provokator sesuai hukum", "s":5},{"t":"Menindak tegas tanpa memihak kelompok mana pun", "s":4},{"t":"Membela kelompok dari daerah Anda", "s":3},{"t":"Membiarkan bentrok selesai sendiri", "s":2},{"t":"Ikut memukuli salah satu kelompok", "s":1}], "ex":"Aparat keamanan netral dari sentimen kedaerahan. Ketegasan yang adil memulihkan ketertiban tanpa dendam suku."},
{"id":"TKP-3262", "q":"Warga transmigran dan warga lokal beda suku berselisih soal jadwal irigasi. Sebagai mantri tani, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menyusun jadwal irigasi yang adil berbasis luas lahan dan kebutuhan, disepakati bersama", "s":5},{"t":"Mengatur pembagian air secara teknis dan berkeadilan", "s":4},{"t":"Memprioritaskan warga lokal", "s":3},{"t":"Memprioritaskan transmigran", "s":2},{"t":"Membiarkan berebut", "s":1}], "ex":"Air irigasi dibagi berbasis kebutuhan teknis, bukan kesukuan. Keadilan teknis meredam sentimen pendatang versus lokal."},
{"id":"TKP-3263", "q":"Perebutan lapak antara pedagang lama dan baru beda suku memanas di pasar tradisional. Sebagai kepala pasar, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menegakkan sistem alokasi lapak yang transparan dan adil bagi semua pedagang", "s":5},{"t":"Menerapkan aturan antrean lapak yang jelas", "s":4},{"t":"Mempertahankan pedagang lama", "s":3},{"t":"Mengusir pedagang baru", "s":2},{"t":"Melelang lapak ke penawar tertinggi diam-diam", "s":1}], "ex":"Alokasi lapak berbasis aturan transparan menutup celah primordialisme. Pasar yang adil menyejahterakan semua suku."},
{"id":"TKP-3264", "q":"Dua keluarga beda keyakinan bertetangga berselisih soal batas pagar. Ketegangan membawa-bawa keyakinan. Sebagai mediator, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Mengembalikan fokus pada data batas tanah, meredam isu keyakinan, dan memfasilitasi kesepakatan", "s":5},{"t":"Menyelesaikan berbasis fakta tanpa sentimen keyakinan", "s":4},{"t":"Memihak yang sekeyakinan dengan Anda", "s":3},{"t":"Membiarkan berselisih", "s":2},{"t":"Memperkeruh dengan isu keyakinan", "s":1}], "ex":"Sengketa batas diselesaikan dengan data, bukan keyakinan. Mediator yang baik memisahkan isu teknis dari sentimen."},
{"id":"TKP-3265", "q":"Kelompok warga menolak pembangunan rumah ibadah dengan alasan lalu lintas, padahal motifnya keyakinan. Sebagai aparat, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Memverifikasi alasan teknis secara objektif, memfasilitasi dialog, dan menegakkan regulasi perizinan yang adil", "s":5},{"t":"Menegakkan aturan dengan musyawarah yang jujur", "s":4},{"t":"Menolak izin mengikuti desakan warga", "s":3},{"t":"Memberi izin tanpa dialog", "s":2},{"t":"Ikut memprovokasi penolakan", "s":1}], "ex":"Penolakan berkedok teknis harus diuji objektif. Regulasi yang adil tidak tunduk pada tekanan mayoritas keyakinan."},
{"id":"TKP-3266", "q":"Anak-anak dua kampung beda suku tawuran dipicu ejekan di pertandingan bola. Sebagai pelatih, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Mendamaikan, menanamkan sportivitas, dan mengadakan pertandingan persahabatan lanjutan", "s":5},{"t":"Membina sportivitas dan perdamaian", "s":4},{"t":"Membela kampung sendiri", "s":3},{"t":"Membubarkan tim", "s":2},{"t":"Memprovokasi tawuran balasan", "s":1}], "ex":"Olahraga adalah bahasa persatuan lintas suku. Sportivitas yang ditanamkan mengubah rivalitas menjadi persaudaraan."},
{"id":"TKP-3267", "q":"Warga suku minoritas melapor ke polisi atas penganiayaan oleh warga mayoritas, tetapi laporannya diabaikan. Sebagai atasan polisi, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Memerintahkan penindaklanjutan laporan secara profesional tanpa memandang suku pelapor maupun terlapor", "s":5},{"t":"Menegakkan proses hukum yang setara", "s":4},{"t":"Membiarkan laporan terabaikan", "s":3},{"t":"Menekan pelapor mencabut laporan", "s":2},{"t":"Melindungi pelaku karena se-suku", "s":1}], "ex":"Hukum melindungi semua suku secara setara. Mengabaikan laporan minoritas adalah pengkhianatan terhadap keadilan."},
{"id":"TKP-3268", "q":"Dua koperasi beda latar suku bersaing tidak sehat dengan fitnah. Sebagai pembina koperasi, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Membina persaingan sehat, menegakkan aturan, dan mendorong kolaborasi yang saling menguntungkan", "s":5},{"t":"Menertibkan dengan pembinaan yang adil", "s":4},{"t":"Membela koperasi yang sesuku dengan Anda", "s":3},{"t":"Membubarkan keduanya", "s":2},{"t":"Ikut menyebarkan fitnah", "s":1}], "ex":"Persaingan usaha tidak boleh menunggangi sentimen suku. Pembinaan adil mengubah rival menjadi mitra."},
{"id":"TKP-3269", "q":"Sengketa parkir antara warga asli dan pendatang beda suku berujung perkelahian. Sebagai ketua RW, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Mendamaikan, mengatur sistem parkir yang adil, dan menegaskan aturan berlaku sama bagi semua warga", "s":5},{"t":"Menata parkir dengan aturan yang setara", "s":4},{"t":"Memihak warga asli", "s":3},{"t":"Mengusir pendatang", "s":2},{"t":"Membiarkan perkelahian", "s":1}], "ex":"Aturan parkir yang adil menutup celah sentimen asli versus pendatang. Keadilan prosedural meredam konflik horizontal."},
{"id":"TKP-3270", "q":"Warga dua keyakinan berselisih soal penggunaan balai desa untuk kegiatan masing-masing di waktu bersamaan. Sebagai pengelola, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menyusun jadwal pakai bergilir yang adil dan transparan, disepakati kedua belah pihak", "s":5},{"t":"Mengatur penjadwalan yang berimbang", "s":4},{"t":"Memberikan ke yang mengajukan lebih dulu selalu", "s":3},{"t":"Menutup balai untuk kegiatan keagamaan", "s":2},{"t":"Memihak satu keyakinan", "s":1}], "ex":"Fasilitas publik dibagi dengan jadwal yang adil. Transparansi penjadwalan mencegah kecurigaan antar keyakinan."},
{"id":"TKP-3271", "q":"Seorang jurnalis warga menulis berita yang menyudutkan satu suku dalam konflik lahan. Sebagai dewan pers komunitas, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Membina jurnalis tentang kode etik, meminta klarifikasi berimbang, dan mencegah pemberitaan provokatif", "s":5},{"t":"Menegakkan jurnalisme damai yang berimbang", "s":4},{"t":"Membiarkan beritanya", "s":3},{"t":"Ikut menyebarkan beritanya", "s":2},{"t":"Melarang semua pemberitaan konflik", "s":1}], "ex":"Jurnalisme warga yang tidak berimbang bisa menyulut konflik suku. Kode etik adalah rem bagi pemberitaan provokatif."},
{"id":"TKP-3272", "q":"Dua kelompok nelayan beda suku berebut zona tangkap. Sebagai syahbandar, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menegakkan zonasi resmi yang adil, memfasilitasi kesepakatan operasional, dan menindak pelanggaran", "s":5},{"t":"Mengatur zona tangkap berbasis aturan yang setara", "s":4},{"t":"Memihak kelompok yang lebih dulu melaut", "s":3},{"t":"Membiarkan berebut", "s":2},{"t":"Menutup seluruh zona tangkap", "s":1}], "ex":"Laut adalah milik bersama yang diatur negara. Zonasi adil berbasis aturan menertibkan tanpa memihak suku."},
{"id":"TKP-3273", "q":"Warga beda suku menuduh perangkat desa pilih kasih dalam penyaluran BLT. Sebagai perangkat yang dituduh, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Membuka data penerima dan kriteria secara transparan, mempersilakan verifikasi bersama", "s":5},{"t":"Menjawab tuduhan dengan keterbukaan data", "s":4},{"t":"Mengabaikan tuduhan", "s":3},{"t":"Mengurangi jatah suku penuduh", "s":2},{"t":"Melaporkan penuduh sebagai pencemaran nama", "s":1}], "ex":"Tuduhan pilih kasih suku dijawab dengan transparansi, bukan emosi. Data terbuka adalah pembelaan terbaik aparatur."},
{"id":"TKP-3274", "q":"Konflik antara peternak lokal dan pendatang beda suku soal penggembalaan ternak memanas. Sebagai perangkat desa, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Memfasilitasi musyawarah penetapan zona dan jadwal gembala yang adil bagi kedua belah pihak", "s":5},{"t":"Mengatur pemanfaatan lahan gembala bersama", "s":4},{"t":"Melarang pendatang menggembala", "s":3},{"t":"Mengusir salah satu pihak", "s":2},{"t":"Membiarkan ternak berebut lahan", "s":1}], "ex":"Lahan gembala komunal diatur dengan musyawarah yang adil. Aturan bersama mencegah konflik lokal versus pendatang."},
{"id":"TKP-3275", "q":"Dua suku berbeda mengklaim sebagai pemilik sah tradisi lisan yang sama untuk pengajuan warisan budaya. Sebagai budayawan, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Memfasilitasi kajian bersama dan pengajuan kolektif yang mengakui kedua belah pihak sebagai pewaris bersama", "s":5},{"t":"Mendorong pengakuan bersama atas warisan budaya", "s":4},{"t":"Memutuskan satu pihak sebagai pemilik", "s":3},{"t":"Menolak pengajuan keduanya", "s":2},{"t":"Memihak suku yang lebih berpengaruh", "s":1}], "ex":"Warisan budaya yang diklaim bersama sebaiknya diakui bersama. Kolaborasi pewarisan lebih mulia daripada perebutan klaim."},
{"id":"TKP-3276", "q":"Warga lanjut usia dari salah satu suku setempat hanya bisa berbahasa daerahnya dan tidak paham surat panggilan vaksinasi. Tindakan Anda sebagai petugas kesehatan yang paling tepat adalah ....", "opts":[{"t":"Mendatanginya dengan pendamping yang paham bahasanya, menjelaskan dengan sabar hingga ia bersedia divaksin", "s":5},{"t":"Berupaya berkomunikasi melalui perantara yang dipahaminya", "s":4},{"t":"Menganggapnya sudah menerima surat", "s":3},{"t":"Mencoretnya dari daftar sasaran", "s":2},{"t":"Mengabaikan karena sulit berkomunikasi", "s":1}], "ex":"Hambatan bahasa bukan alasan mengabaikan hak kesehatan lansia. Pendekatan personal dengan bahasa ibu adalah pelayanan humanis."},
{"id":"TKP-3277", "q":"Kantin sekolah hanya menjual makanan yang tidak sesuai pantangan keyakinan sebagian siswa. Sebagai kepala sekolah, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Mewajibkan variasi menu kantin yang mengakomodasi pantangan keyakinan siswa", "s":5},{"t":"Mengatur keragaman menu yang inklusif", "s":4},{"t":"Menyarankan siswa membawa bekal", "s":3},{"t":"Membiarkan karena urusan penyewa kantin", "s":2},{"t":"Menganggap tuntutan siswa berlebihan", "s":1}], "ex":"Kantin sekolah melayani semua keyakinan siswanya. Keberagaman menu adalah bagian dari pendidikan toleransi."},
{"id":"TKP-3278", "q":"Pegawai baru diminta melepas penutup kepala adatnya saat bertugas karena dianggap tidak seragam. Aturan tidak eksplisit melarang. Sikap Anda sebagai atasan yang paling tepat adalah ....", "opts":[{"t":"Mengizinkan sepanjang tidak mengganggu tugas dan keselamatan, menghormati identitas budayanya", "s":5},{"t":"Memberikan toleransi berbusana dalam koridor kepantasan", "s":4},{"t":"Memaksanya melepas demi keseragaman", "s":3},{"t":"Memberi sanksi disiplin", "s":2},{"t":"Menertawakan penutup kepalanya", "s":1}], "ex":"Identitas budaya dalam berbusana adalah hak yang dihormati. Keseragaman dinas tidak harus menghapus jati diri."},
{"id":"TKP-3279", "q":"Dalam jamuan resmi desa, hidangan yang disajikan tidak memperhatikan pantangan keyakinan sebagian tamu. Sebagai panitia, yang paling tepat Anda lakukan ke depan adalah ....", "opts":[{"t":"Menyediakan variasi hidangan yang mengakomodasi pantangan keyakinan tamu sebagai standar kepanitiaan", "s":5},{"t":"Merencanakan menu inklusif sejak awal", "s":4},{"t":"Meminta tamu yang berpantangan tidak hadir", "s":3},{"t":"Mengabaikan karena mayoritas tidak berpantangan", "s":2},{"t":"Menyindir keyakinan tamu yang berpantangan", "s":1}], "ex":"Jamuan resmi yang baik memuliakan semua tamu lintas keyakinan. Perencanaan menu inklusif adalah etiket kepanitiaan."},
{"id":"TKP-3280", "q":"Warga pendatang tidak paham bahasa isyarat lokal (gestur) sehingga terjadi salah paham dengan warga asli yang berbeda suku. Sebagai perangkat desa, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Memfasilitasi dialog, menjelaskan perbedaan makna gestur budaya, dan mendamaikan kedua belah pihak", "s":5},{"t":"Menjembatani kesalahpahaman komunikasi budaya", "s":4},{"t":"Membela warga asli", "s":3},{"t":"Mengusir pendatang", "s":2},{"t":"Menertawakan kebodohan pendatang", "s":1}], "ex":"Gestur punya makna berbeda antar budaya. Kesalahpahaman komunikasi diselesaikan dengan penjelasan, bukan penghakiman."},
{"id":"TKP-3281", "q":"Siswa mengenakan pakaian adatnya di hari Jumat menggantikan seragam karena alasan keyakinan budaya. Aturan sekolah mewajibkan seragam. Sebagai guru, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menghargai ekspresi budayanya, berdialog dengan orang tua, dan mencari kesepakatan penjadwalan hari budaya", "s":5},{"t":"Memfasilitasi solusi yang menghormati budaya dan aturan", "s":4},{"t":"Menghukumnya karena melanggar aturan", "s":3},{"t":"Mengusirnya dari kelas", "s":2},{"t":"Menertawakan pakaiannya", "s":1}], "ex":"Kebanggaan budaya siswa disalurkan lewat hari budaya resmi. Dialog menghasilkan aturan yang hidup dan dihormati."},
{"id":"TKP-3282", "q":"Puskesmas akan membagikan makanan tambahan balita, tetapi menunya mengandung bahan yang dipantangkan keyakinan sebagian keluarga. Yang paling tepat dilakukan adalah ....", "opts":[{"t":"Menyediakan alternatif menu yang sesuai pantangan keyakinan agar semua balita terlayani", "s":5},{"t":"Menyesuaikan menu dengan kebutuhan keberagaman", "s":4},{"t":"Membagikan apa adanya", "s":3},{"t":"Mencoret keluarga yang menolak menu", "s":2},{"t":"Menyalahkan keyakinan mereka", "s":1}], "ex":"Program gizi anak tidak boleh tersandera keseragaman menu. Alternatif yang inklusif memastikan tidak ada balita tertinggal."},
{"id":"TKP-3283", "q":"Warga suku tertentu memiliki pantangan tidak boleh difoto untuk keperluan apapun termasuk KTP. Petugas membutuhkan foto. Solusi Anda yang paling tepat adalah ....", "opts":[{"t":"Menghormati pantangannya dan menggunakan alternatif identifikasi resmi yang disepakati seperti sidik jari", "s":5},{"t":"Mencarikan pengganti foto yang sah", "s":4},{"t":"Memaksa foto", "s":3},{"t":"Menolak melayani", "s":2},{"t":"Memfotonya diam-diam", "s":1}], "ex":"Pantangan budaya adalah hak yang dilindungi. Administrasi modern selalu menyediakan alternatif identifikasi yang manusiawi."},
{"id":"TKP-3284", "q":"Dalam pelatihan, instruktur menggunakan contoh yang hanya familiar bagi satu suku sehingga peserta lain bingung. Sebagai peserta, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Mengusulkan dengan sopan agar contoh divariasikan supaya semua peserta dari berbagai suku memahami", "s":5},{"t":"Memberi masukan konstruktif tentang keberagaman contoh", "s":4},{"t":"Diam dan tidak memahami materi", "s":3},{"t":"Memprotes dengan kasar", "s":2},{"t":"Meninggalkan pelatihan", "s":1}], "ex":"Contoh pembelajaran yang inklusif mempercepat pemahaman semua peserta. Masukan sopan memperbaiki kualitas pelatihan."},
{"id":"TKP-3285", "q":"Warung makan khas budaya daerah Anda dikunjungi wisatawan asing yang meminta penjelasan menu dalam bahasa yang tidak Anda kuasai. Sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Berusaha menjelaskan dengan bahasa isyarat, gambar menu, dan keramahan hingga ia memahami", "s":5},{"t":"Membantu dengan segala cara komunikasi yang tersedia", "s":4},{"t":"Mengusir karena tidak bisa berkomunikasi", "s":3},{"t":"Menaikkan harga karena ia orang asing", "s":2},{"t":"Menertawakannya", "s":1}], "ex":"Keramahan melampaui batas bahasa. Usaha menjelaskan dengan segala cara adalah wajah pariwisata Indonesia."},
{"id":"TKP-3286", "q":"Pegawai diminta menjadi pembawa acara dengan bahasa daerah salah satu suku, padahal ia tidak menguasainya. Ia takut mengecewakan. Sebagai atasan, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menugaskan sesuai kompetensinya dan mencari pembawa acara yang tepat, tanpa memaksakan identitas suku", "s":5},{"t":"Menyesuaikan penugasan dengan kemampuan nyata", "s":4},{"t":"Memaksanya demi representasi suku", "s":3},{"t":"Membatalkan acara", "s":2},{"t":"Mempermalukannya di depan umum", "s":1}], "ex":"Representasi suku tidak boleh mengorbankan kompetensi. Penugasan yang tepat menghormati individu dan acara."},
{"id":"TKP-3287", "q":"Keluarga pasien meminta makanan rumah sakit diganti karena pantangan keyakinannya. Dapur rumah sakit keberatan. Sebagai manajemen, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Mewajibkan dapur menyediakan opsi menu sesuai pantangan keyakinan sebagai standar layanan pasien", "s":5},{"t":"Mengatur layanan gizi yang akomodatif", "s":4},{"t":"Meminta keluarga membawa makanan sendiri", "s":3},{"t":"Menolak dengan alasan efisiensi", "s":2},{"t":"Menyalahkan keyakinan pasien", "s":1}], "ex":"Gizi pasien adalah bagian penyembuhan yang wajib menghormati keyakinan. Standar layanan inklusif adalah kewajiban rumah sakit."},
{"id":"TKP-3288", "q":"Anak Anda diejek karena bekal makanannya berbeda dengan teman-temannya akibat pantangan keyakinan. Sikap Anda yang paling tepat adalah ....", "opts":[{"t":"Menguatkannya bahwa perbedaan bekal adalah hal biasa, berkoordinasi dengan guru menanamkan toleransi di kelas", "s":5},{"t":"Membangun kepercayaan dirinya dan melibatkan sekolah", "s":4},{"t":"Mengganti bekalnya agar sama dengan teman", "s":3},{"t":"Menyuruhnya tidak makan di sekolah", "s":2},{"t":"Memarahinya karena cengeng", "s":1}], "ex":"Perbedaan bekal karena keyakinan bukan aib. Anak yang dikuatkan tumbuh menjadi pribadi toleran yang percaya diri."},
{"id":"TKP-3289", "q":"Warga meminta penerjemah bahasa isyarat daerahnya dalam sidang sengketa tanah adat. Pengadilan tidak menyediakannya. Sebagai pendamping, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Mengupayakan penerjemah yang kompeten demi keadilan, berkoordinasi dengan pengadilan", "s":5},{"t":"Memfasilitasi haknya didengar dengan bahasa yang dipahami", "s":4},{"t":"Membiarkannya mengikuti sidang tanpa paham", "s":3},{"t":"Menarik perkaranya", "s":2},{"t":"Menganggap bahasanya tidak penting", "s":1}], "ex":"Keadilan mensyaratkan pemahaman. Hak atas penerjemah adalah hak asasi dalam proses hukum bagi penutur bahasa minoritas."},
{"id":"TKP-3290", "q":"Dalam upacara adat penyambutan tamu, tamu berbeda keyakinan diminta mengikuti ritual yang bertentangan dengan keyakinannya. Sebagai tuan rumah, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Memberinya pilihan menghormati dengan cara yang tidak bertentangan dengan keyakinannya, tanpa paksaan", "s":5},{"t":"Menyediakan alternatif penghormatan yang inklusif", "s":4},{"t":"Memaksanya mengikuti seluruh ritual", "s":3},{"t":"Mengusirnya dari acara", "s":2},{"t":"Mempermalukannya di depan hadirin", "s":1}], "ex":"Tamu dimuliakan bukan dipaksa. Adat penyambutan yang bijak memberi ruang bagi keyakinan tamu."},
{"id":"TKP-3291", "q":"Seorang pramugari diminta melepas atribut keyakinannya oleh maskapai dengan alasan keseragaman. Aturan tidak tertulis. Sikap serikat pekerja yang paling tepat adalah ....", "opts":[{"t":"Mengadvokasi haknya berbusana sesuai keyakinan sepanjang tidak mengganggu keselamatan dan pelayanan", "s":5},{"t":"Membela hak konstitusionalnya melalui jalur resmi", "s":4},{"t":"Memintanya mematuhi maskapai", "s":3},{"t":"Membiarkannya berjuang sendiri", "s":2},{"t":"Mendukung maskapai", "s":1}], "ex":"Keseragaman perusahaan tidak boleh menghapus hak berkeyakinan pekerja. Advokasi resmi melindungi tanpa merusak hubungan industrial."},
{"id":"TKP-3292", "q":"Warga suku pedalaman menolak program imunisasi karena makanan yang dibagikan petugas mengandung pantangan adatnya. Pendekatan Anda yang paling tepat adalah ....", "opts":[{"t":"Mengganti menu dengan yang sesuai adat dan menjelaskan manfaat imunisasi melalui tokoh adat", "s":5},{"t":"Menyesuaikan layanan dengan nilai adat setempat", "s":4},{"t":"Memaksa imunisasi tanpa makanan", "s":3},{"t":"Membatalkan program di wilayah itu", "s":2},{"t":"Menyebut adatnya sebagai penghalang kesehatan", "s":1}], "ex":"Layanan kesehatan yang peka adat diterima dengan hati terbuka. Penyesuaian kecil membuka pintu program besar."},
{"id":"TKP-3293", "q":"Dalam lomba masak antar daerah, juri meremehkan masakan suku minoritas sebagai tidak berkelas. Sebagai ketua juri, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menegur dan memastikan penilaian berbasis rasa dan teknik, bukan asal suku masakan", "s":5},{"t":"Menegakkan objektivitas penilaian", "s":4},{"t":"Membiarkan penilaian juri", "s":3},{"t":"Ikut meremehkan", "s":2},{"t":"Mendiskualifikasi masakan minoritas", "s":1}], "ex":"Cita rasa tidak mengenal kasta suku. Penilaian objektif adalah kehormatan profesi juri."},
{"id":"TKP-3294", "q":"Pegawai kontrak berbeda suku selalu ditempatkan di posisi paling berat tanpa rotasi. Ia menduga diskriminasi. Sebagai atasan, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Mengevaluasi sistem pembagian tugas, menerapkan rotasi yang adil, dan memastikan tidak ada bias suku", "s":5},{"t":"Memperbaiki distribusi tugas secara berkeadilan", "s":4},{"t":"Menganggapnya kebetulan", "s":3},{"t":"Memecatnya karena dianggap pembangkang", "s":2},{"t":"Menambah bebannya", "s":1}], "ex":"Dugaan diskriminasi struktural dijawab dengan audit sistem. Rotasi adil melindungi semua pegawai lintas suku."},
{"id":"TKP-3295", "q":"Warga meminta papan informasi desa ditulis dalam aksara budaya daerahnya selain bahasa Indonesia. Sebagian menganggap pemborosan. Sebagai kepala desa, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Mewujudkannya secara bertahap sebagai investasi kebanggaan budaya dan identitas desa", "s":5},{"t":"Mengakomodasi secara proporsional sesuai anggaran", "s":4},{"t":"Menolak karena alasan biaya", "s":3},{"t":"Mengabaikan usulan", "s":2},{"t":"Mengejek aksara daerahnya", "s":1}], "ex":"Aksara daerah di ruang publik adalah pernyataan kebanggaan identitas. Investasi budaya memperkuat jati diri desa."},
{"id":"TKP-3296", "q":"Dalam pelatihan baris-berbaris, peserta berhijab/berpenutup kepala adat kesulitan mengikuti gerakan tertentu. Instruktur memaksanya melepas. Sikap instruktur yang paling tepat adalah ....", "opts":[{"t":"Menyesuaikan teknik gerakan tanpa mengharuskan melepas penutup kepala, menghormati keyakinannya", "s":5},{"t":"Mencarikan solusi gerakan yang akomodatif", "s":4},{"t":"Memaksa melepas demi keseragaman", "s":3},{"t":"Mengeluarkannya dari pelatihan", "s":2},{"t":"Mempermalukannya di depan peserta", "s":1}], "ex":"Kedisiplinan tidak menuntut penyeragaman keyakinan. Instruktur kreatif menemukan cara tanpa melanggar prinsip peserta."},
{"id":"TKP-3297", "q":"Seorang turis asing tersesat di kampung adat dan tidak bisa berbahasa Indonesia. Warga curiga ia mata-mata. Sebagai perangkat desa, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menyambutnya baik, membantu dengan bahasa isyarat atau penerjemah, dan memastikan keamanannya", "s":5},{"t":"Memberikan pertolongan selayaknya tamu", "s":4},{"t":"Mengusirnya dari kampung", "s":3},{"t":"Melaporkannya sebagai ancaman", "s":2},{"t":"Menahannya tanpa dasar", "s":1}], "ex":"Praduga baik kepada tamu asing mencerminkan keramahan bangsa. Bantuan yang tulus adalah diplomasi rakyat terbaik."},
{"id":"TKP-3298", "q":"Anak panti asuhan berbeda-beda keyakinan diasuh dalam satu panti. Pengasuh bingung mengatur ibadah. Yang paling tepat dilakukan adalah ....", "opts":[{"t":"Memfasilitasi ibadah masing-masing keyakinan secara adil dan menanamkan saling menghormati antar anak", "s":5},{"t":"Mengatur jadwal dan ruang ibadah yang berkeadilan", "s":4},{"t":"Menyeragamkan ibadah mengikuti mayoritas", "s":3},{"t":"Melarang ibadah di panti", "s":2},{"t":"Memisahkan anak berdasarkan keyakinan", "s":1}], "ex":"Panti yang merangkul semua keyakinan mendidik toleransi sejak dini. Keadilan fasilitas ibadah adalah kasih sayang yang nyata."},
{"id":"TKP-3299", "q":"Warga mengeluh baliho caleg menutupi papan nama rumah ibadahnya. Caleg tersebut sekeyakinan dengan pengurus. Sebagai panwas, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menegakkan aturan penempatan alat peraga secara netral tanpa memandang keyakinan caleg", "s":5},{"t":"Menertibkan berdasarkan aturan yang berlaku", "s":4},{"t":"Membiarkan karena sekeyakinan", "s":3},{"t":"Memerintahkan pencopotan sepihak", "s":2},{"t":"Ikut memasang baliho tandingan", "s":1}], "ex":"Penegakan aturan pemilu buta terhadap keyakinan peserta. Netralitas panwas menjaga marwah demokrasi."},
{"id":"TKP-3300", "q":"Generasi muda kampung malu menggunakan bahasa daerah sukunya di depan pendatang. Sebagai tokoh masyarakat, yang paling tepat Anda lakukan adalah ....", "opts":[{"t":"Menjadikan bahasa daerah kebanggaan melalui lomba, konten kreatif, dan keteladanan penggunaannya", "s":5},{"t":"Membangun kebanggaan berbahasa daerah", "s":4},{"t":"Mewajibkan dengan sanksi", "s":3},{"t":"Membiarkan bahasa daerah punah", "s":2},{"t":"Mengejek yang tidak bisa berbahasa daerah", "s":1}], "ex":"Bahasa daerah adalah warisan leluhur yang hidup di lidah generasi muda. Kebanggaan menuturkannya adalah pelestarian terbaik."}
];
